1	import type { AgentStreamEvent } from '@lobechat/agent-gateway-client';
2	import type { HeterogeneousAgentEvent, ToolCallPayload } from '@lobechat/heterogeneous-agents';
3	import { createAdapter } from '@lobechat/heterogeneous-agents';
4	import type {
5	  ChatToolPayload,
6	  ConversationContext,
7	  HeterogeneousProviderConfig,
8	} from '@lobechat/types';
9	
10	import { heterogeneousAgentService } from '@/services/electron/heterogeneousAgent';
11	import { messageService } from '@/services/message';
12	import type { ChatStore } from '@/store/chat/store';
13	
14	import { createGatewayEventHandler } from './gatewayEventHandler';
15	
16	export interface HeterogeneousAgentExecutorParams {
17	  assistantMessageId: string;
18	  context: ConversationContext;
19	  heterogeneousProvider: HeterogeneousProviderConfig;
20	  /** Image attachments from user message — passed to Main for vision support */
21	  imageList?: Array<{ id: string; url: string }>;
22	  message: string;
23	  operationId: string;
24	  workingDirectory?: string;
25	}
26	
27	/**
28	 * Map heterogeneousProvider.command to adapter type key.
29	 */
30	const resolveAdapterType = (config: HeterogeneousProviderConfig): string => {
31	  // Explicit adapterType in config takes priority
32	  if ((config as any).adapterType) return (config as any).adapterType;
33	
34	  // Infer from command name
35	  const cmd = config.command || 'claude';
36	  if (cmd.includes('claude')) return 'claude-code';
37	  if (cmd.includes('codex')) return 'codex';
38	  if (cmd.includes('kimi')) return 'kimi-cli';
39	
40	  return 'claude-code'; // default
41	};
42	
43	/**
44	 * Convert HeterogeneousAgentEvent to AgentStreamEvent (add operationId).
45	 */
46	const toStreamEvent = (event: HeterogeneousAgentEvent, operationId: string): AgentStreamEvent => ({
47	  data: event.data,
48	  operationId,
49	  stepIndex: event.stepIndex,
50	  timestamp: event.timestamp,
51	  type: event.type as AgentStreamEvent['type'],
52	});
53	
54	/**
55	 * Subscribe to Electron IPC broadcasts for raw agent lines.
56	 * Returns unsubscribe function.
57	 */
58	const subscribeBroadcasts = (
59	  sessionId: string,
60	  callbacks: {
61	    onComplete: () => void;
62	    onError: (error: string) => void;
63	    onRawLine: (line: any) => void;
64	  },
65	): (() => void) => {
66	  if (!window.electron?.ipcRenderer) return () => {};
67	
68	  const ipc = window.electron.ipcRenderer;
69	
70	  const onLine = (_e: any, data: { line: any; sessionId: string }) => {
71	    if (data.sessionId === sessionId) callbacks.onRawLine(data.line);
72	  };
73	  const onComplete = (_e: any, data: { sessionId: string }) => {
74	    if (data.sessionId === sessionId) callbacks.onComplete();
75	  };
76	  const onError = (_e: any, data: { error: string; sessionId: string }) => {
77	    if (data.sessionId === sessionId) callbacks.onError(data.error);
78	  };
79	
80	  ipc.on('heteroAgentRawLine' as any, onLine);
81	  ipc.on('heteroAgentSessionComplete' as any, onComplete);
82	  ipc.on('heteroAgentSessionError' as any, onError);
83	
84	  return () => {
85	    ipc.removeListener('heteroAgentRawLine' as any, onLine);
86	    ipc.removeListener('heteroAgentSessionComplete' as any, onComplete);
87	    ipc.removeListener('heteroAgentSessionError' as any, onError);
88	  };
89	};
90	
91	/**
92	 * Persisted tool-call registry for a single ACP execution.
93	 *
94	 * Tracks which tool_use ids have been persisted to avoid duplicates,
95	 * and holds the enriched payload (with result_msg_id) that gets written
96	 * back to the assistant message's tools JSONB.
97	 */
98	interface ToolPersistenceState {
99	  /** Ordered list of ChatToolPayload[] written to assistant.tools */
100	  payloads: ChatToolPayload[];
101	  /** Set of tool_use.id that have been persisted (de-dupe guard) */
102	  persistedIds: Set<string>;
103	  /** Map tool_use.id → tool message DB id (for later content update on tool_result) */
104	  toolMsgIdByCallId: Map<string, string>;
105	}
106	
107	/**
108	 * Persist any newly-seen tool calls and update the assistant message's tools JSONB.
109	 *
110	 * Guarantees:
111	 * - One tool message per unique tool_use.id (idempotent against re-processing)
112	 * - assistant.tools[].result_msg_id is set to the created tool message id, so
113	 *   the UI's parse() step can link tool messages back to the assistant turn
114	 *   (otherwise they render as orphan warnings).
115	 */
116	const persistNewToolCalls = async (
117	  incoming: ToolCallPayload[],
118	  state: ToolPersistenceState,
119	  assistantMessageId: string,
120	  context: ConversationContext,
121	) => {
122	  const freshTools = incoming.filter((t) => !state.persistedIds.has(t.id));
123	  if (freshTools.length === 0) return;
124	
125	  // Mark all fresh tools as persisted up front, so re-entrant calls (from
126	  // Claude Code echoing tool_use blocks) are safely deduped.
127	  for (const tool of freshTools) state.persistedIds.add(tool.id);
128	
129	  // ─── PHASE 1: Write tools[] to assistant FIRST, WITHOUT result_msg_id ───
130	  //
131	  // LobeHub's conversation-flow parser filters tool messages by matching
132	  // `tool.tool_call_id` against `assistant.tools[].id`. If a tool message
133	  // exists in DB but no matching entry exists in assistant.tools[], the UI
134	  // renders an "orphan" warning telling the user to delete it.
135	  //
136	  // By writing assistant.tools[] FIRST (with the tool ids but no result_msg_id
137	  // yet), the match works from the moment tool messages get created in DB.
138	  // No orphan window.
139	  for (const tool of freshTools) state.payloads.push({ ...tool } as ChatToolPayload);
140	  try {
141	    await messageService.updateMessage(
142	      assistantMessageId,
143	      { tools: state.payloads },
144	      { agentId: context.agentId, topicId: context.topicId },
145	    );
146	  } catch (err) {
147	    console.error('[HeterogeneousAgent] Failed to pre-register assistant tools:', err);
148	  }
149	
150	  // ─── PHASE 2: Create the tool messages in DB ───
151	  // Each tool message's tool_call_id matches an already-registered tool id
152	  // in assistant.tools[], so UI never sees orphan state.
153	  for (const tool of freshTools) {
154	    try {
155	      const result = await messageService.createMessage({
156	        agentId: context.agentId,
157	        content: '',
158	        parentId: assistantMessageId,
159	        plugin: {
160	          apiName: tool.apiName,
161	          arguments: tool.arguments,
162	          identifier: tool.identifier,
163	          type: tool.type as ChatToolPayload['type'],
164	        },
165	        role: 'tool',
166	        tool_call_id: tool.id,
167	        topicId: context.topicId ?? undefined,
168	      });
169	      state.toolMsgIdByCallId.set(tool.id, result.id);
170	      // Back-fill result_msg_id onto the payload we pushed in PHASE 1
171	      const entry = state.payloads.find((p) => p.id === tool.id);
172	      if (entry) entry.result_msg_id = result.id;
173	    } catch (err) {
174	      console.error('[HeterogeneousAgent] Failed to create tool message:', err);
175	    }
176	  }
177	
178	  // ─── PHASE 3: Re-write assistant.tools[] with the result_msg_ids ───
179	  // Without this, the UI can't hydrate tool results back into the inspector.
180	  try {
181	    await messageService.updateMessage(
182	      assistantMessageId,
183	      { tools: state.payloads },
184	      { agentId: context.agentId, topicId: context.topicId },
185	    );
186	  } catch (err) {
187	    console.error('[HeterogeneousAgent] Failed to finalize assistant tools:', err);
188	  }
189	};
190	
191	/**
192	 * Update a tool message's content in DB when tool_result arrives.
193	 */
194	const persistToolResult = async (
195	  toolCallId: string,
196	  content: string,
197	  isError: boolean,
198	  state: ToolPersistenceState,
199	  context: ConversationContext,
200	) => {
201	  const toolMsgId = state.toolMsgIdByCallId.get(toolCallId);
202	  if (!toolMsgId) {
203	    console.warn('[HeterogeneousAgent] tool_result for unknown toolCallId:', toolCallId);
204	    return;
205	  }
206	
207	  try {
208	    await messageService.updateToolMessage(
209	      toolMsgId,
210	      {
211	        content,
212	        pluginError: isError ? { message: content } : undefined,
213	      },
214	      {
215	        agentId: context.agentId,
216	        topicId: context.topicId,
217	      },
218	    );
219	  } catch (err) {
220	    console.error('[HeterogeneousAgent] Failed to update tool message content:', err);
221	  }
222	};
223	
224	/**
225	 * Execute a prompt via an external agent CLI.
226	 *
227	 * Flow:
228	 * 1. Subscribe to IPC broadcasts
229	 * 2. Spawn agent process via heterogeneousAgentService
230	 * 3. Raw stdout lines → Adapter → HeterogeneousAgentEvent → AgentStreamEvent
231	 * 4. Feed AgentStreamEvents into createGatewayEventHandler (unified handler)
232	 * 5. Tool messages created via messageService before emitting tool events
233	 */
234	export const executeHeterogeneousAgent = async (
235	  get: () => ChatStore,
236	  params: HeterogeneousAgentExecutorParams,
237	): Promise<void> => {
238	  const {
239	    heterogeneousProvider,
240	    assistantMessageId,
241	    context,
242	    imageList,
243	    message,
244	    operationId,
245	    workingDirectory,
246	  } = params;
247	
248	  // Create adapter for this agent type
249	  const adapterType = resolveAdapterType(heterogeneousProvider);
250	  const adapter = createAdapter(adapterType);
251	
252	  // Create the unified event handler (same one Gateway uses)
253	  const eventHandler = createGatewayEventHandler(get, {
254	    assistantMessageId,
255	    context,
256	    operationId,
257	  });
258	
259	  let agentSessionId: string | undefined;
260	  let unsubscribe: (() => void) | undefined;
261	  let completed = false;
262	
263	  // Track state for DB persistence
264	  const toolState: ToolPersistenceState = {
265	    payloads: [],
266	    persistedIds: new Set(),
267	    toolMsgIdByCallId: new Map(),
268	  };
269	  /** Serializes async persist operations so ordering is stable. */
270	  let persistQueue: Promise<void> = Promise.resolve();
271	  /** Tracks the current assistant message being written to (switches on new steps) */
272	  let currentAssistantMessageId = assistantMessageId;
273	  /** Content accumulators — reset on each new step */
274	  let accumulatedContent = '';
275	  let accumulatedReasoning = '';
276	  /** Extracted model + usage from each assistant event (used for final write) */
277	  let lastModel: string | undefined;
278	  const accumulatedUsage: Record<string, number> = {
279	    cache_creation_input_tokens: 0,
280	    cache_read_input_tokens: 0,
281	    input_tokens: 0,
282	    output_tokens: 0,
283	  };
284	  /**
285	   * Deferred terminal event (agent_runtime_end or error). We don't forward
286	   * these to the gateway handler immediately because handler triggers
287	   * fetchAndReplaceMessages which would clobber our in-flight content
288	   * writes with stale DB state. onComplete forwards after persistence.
289	   */
290	  let deferredTerminalEvent: HeterogeneousAgentEvent | null = null;
291	  /**
292	   * True while a step transition is in flight (stream_start queued but not yet
293	   * forwarded to handler). Events that would normally be forwarded sync must
294	   * be deferred through persistQueue so the handler receives stream_start first.
295	   * Without this, tools_calling gets dispatched to the OLD assistant → orphan.
296	   */
297	  let pendingStepTransition = false;
298	
299	  try {
300	    // Start session
301	    const result = await heterogeneousAgentService.startSession({
302	      agentType: adapterType,
303	      args: heterogeneousProvider.args,
304	      command: heterogeneousProvider.command || 'claude',
305	      cwd: workingDirectory,
306	      env: heterogeneousProvider.env,
307	    });
308	    agentSessionId = result.sessionId;
309	    if (!agentSessionId) throw new Error('Agent session returned no sessionId');
310	
311	    // ─── Debug tracing (dev only) ───
312	    const trace: Array<{ adaptedEvents: any[]; rawLine: any; timestamp: number }> = [];
313	    if (typeof window !== 'undefined') {
314	      (window as any).__HETERO_AGENT_TRACE = trace;
315	    }
316	
317	    // Subscribe to broadcasts BEFORE sending prompt
318	    unsubscribe = subscribeBroadcasts(agentSessionId, {
319	      onRawLine: (line) => {
320	        const events = adapter.adapt(line);
321	
322	        // Record for debugging
323	        trace.push({
324	          adaptedEvents: events.map((e) => ({ data: e.data, type: e.type })),
325	          rawLine: line,
326	          timestamp: Date.now(),
327	        });
328	
329	        for (const event of events) {
330	          // ─── tool_result: update tool message content in DB (ACP-only) ───
331	          if (event.type === 'tool_result') {
332	            const { content, isError, toolCallId } = event.data as {
333	              content: string;
334	              isError?: boolean;
335	              toolCallId: string;
336	            };
337	            persistQueue = persistQueue.then(() =>
338	              persistToolResult(toolCallId, content, !!isError, toolState, context),
339	            );
340	            // Don't forward — the tool_end that follows triggers fetchAndReplaceMessages
341	            // which reads the updated content from DB.
342	            continue;
343	          }
344	
345	          // ─── step_complete with turn_metadata: capture model + usage ───
346	          if (event.type === 'step_complete' && event.data?.phase === 'turn_metadata') {
347	            if (event.data.model) lastModel = event.data.model;
348	            if (event.data.usage) {
349	              // Accumulate token usage across all turns
350	              accumulatedUsage.input_tokens += event.data.usage.input_tokens || 0;
351	              accumulatedUsage.output_tokens += event.data.usage.output_tokens || 0;
352	              accumulatedUsage.cache_creation_input_tokens +=
353	                event.data.usage.cache_creation_input_tokens || 0;
354	              accumulatedUsage.cache_read_input_tokens +=
355	                event.data.usage.cache_read_input_tokens || 0;
356	            }
357	            // Don't forward turn metadata — it's internal bookkeeping
358	            continue;
359	          }
360	
361	          // ─── stream_start with newStep: new LLM turn, create new assistant message ───
362	          if (event.type === 'stream_start' && event.data?.newStep) {
363	            // ⚠️ Snapshot CONTENT accumulators synchronously — stream_chunk events for
364	            // the new step arrive in the same onRawLine batch and would contaminate.
365	            // Tool state (toolMsgIdByCallId) is populated ASYNC by persistQueue, so
366	            // it must be read inside the queue where previous persists have completed.
367	            const prevContent = accumulatedContent;
368	            const prevReasoning = accumulatedReasoning;
369	            const prevModel = lastModel;
370	
371	            // Reset content accumulators synchronously so new-step chunks go to fresh state
372	            accumulatedContent = '';
373	            accumulatedReasoning = '';
374	
375	            // Mark that we're in a step transition. Events from the same onRawLine
376	            // batch (stream_chunk, tool_start, etc.) must be deferred through
377	            // persistQueue so the handler receives stream_start FIRST — otherwise
378	            // it dispatches tools to the OLD assistant (orphan tool bug).
379	            pendingStepTransition = true;
380	
381	            persistQueue = persistQueue.then(async () => {
382	              // Persist previous step's content to its assistant message
383	              const prevUpdate: Record<string, any> = {};
384	              if (prevContent) prevUpdate.content = prevContent;
385	              if (prevReasoning) prevUpdate.reasoning = { content: prevReasoning };
386	              if (prevModel) prevUpdate.model = prevModel;
387	              if (Object.keys(prevUpdate).length > 0) {
388	                await messageService
389	                  .updateMessage(currentAssistantMessageId, prevUpdate, {
390	                    agentId: context.agentId,
391	                    topicId: context.topicId,
392	                  })
393	                  .catch(console.error);
394	              }
395	
396	              // Create new assistant message for this step.
397	              // parentId should point to the last tool message from the previous step
398	              // (if any), forming the chain: assistant → tool → assistant → tool → ...
399	              // If no tool was used, fall back to the previous assistant message.
400	              // Read toolMsgIdByCallId HERE (async) because it's populated by prior persists.
401	              const lastToolMsgId = [...toolState.toolMsgIdByCallId.values()].pop();
402	              const stepParentId = lastToolMsgId || currentAssistantMessageId;
403	
404	              const newMsg = await messageService.createMessage({
405	                agentId: context.agentId,
406	                content: '',
407	                model: lastModel,
408	                parentId: stepParentId,
409	                role: 'assistant',
410	                topicId: context.topicId ?? undefined,
411	              });
412	              currentAssistantMessageId = newMsg.id;
413	
414	              // Associate the new message with the operation
415	              get().associateMessageWithOperation(currentAssistantMessageId, operationId);
416	
417	              // Reset tool state AFTER reading — new-step tool persists are queued
418	              // AFTER this handler, so they'll write to the clean state.
419	              toolState.payloads = [];
420	              toolState.persistedIds.clear();
421	              toolState.toolMsgIdByCallId.clear();
422	            });
423	
424	            // Update the stream_start event to carry the new message ID
425	            // so the gateway handler can switch to it
426	            persistQueue = persistQueue.then(() => {
427	              event.data.assistantMessage = { id: currentAssistantMessageId };
428	              eventHandler(toStreamEvent(event, operationId));
429	              // Step transition complete — handler has the new assistant ID now
430	              pendingStepTransition = false;
431	            });
432	            continue;
433	          }
434	
435	          // ─── Defer terminal events so content writes complete first ───
436	          // Gateway handler's agent_runtime_end/error triggers fetchAndReplaceMessages,
437	          // which would read stale DB state (before we persist final content + usage).
438	          if (event.type === 'agent_runtime_end' || event.type === 'error') {
439	            deferredTerminalEvent = event;
440	            continue;
441	          }
442	
443	          // ─── stream_chunk: accumulate content + persist tool_use ───
444	          if (event.type === 'stream_chunk') {
445	            const chunk = event.data;
446	            if (chunk?.chunkType === 'text' && chunk.content) {
447	              accumulatedContent += chunk.content;
448	            }
449	            if (chunk?.chunkType === 'reasoning' && chunk.reasoning) {
450	              accumulatedReasoning += chunk.reasoning;
451	            }
452	            if (chunk?.chunkType === 'tools_calling') {
453	              const tools = chunk.toolsCalling as ToolCallPayload[];
454	              if (tools?.length) {
455	                persistQueue = persistQueue.then(() =>
456	                  persistNewToolCalls(tools, toolState, currentAssistantMessageId, context),
457	                );
458	              }
459	            }
460	          }
461	
462	          // Forward to the unified Gateway handler.
463	          // If a step transition is pending, defer through persistQueue so the
464	          // handler receives stream_start (with new assistant ID) FIRST.
465	          if (pendingStepTransition) {
466	            const snapshot = toStreamEvent(event, operationId);
467	            persistQueue = persistQueue.then(() => {
468	              eventHandler(snapshot);
469	            });
470	          } else {
471	            eventHandler(toStreamEvent(event, operationId));
472	          }
473	        }
474	      },
475	
476	      onComplete: async () => {
477	        if (completed) return;
478	        completed = true;
479	
480	        // Flush remaining adapter state (e.g., still-open tool_end events — but
481	        // NOT agent_runtime_end; that's deferred below)
482	        const flushEvents = adapter.flush();
483	        for (const event of flushEvents) {
484	          if (event.type === 'agent_runtime_end' || event.type === 'error') {
485	            deferredTerminalEvent = event;
486	            continue;
487	          }
488	          eventHandler(toStreamEvent(event, operationId));
489	        }
490	
491	        // Wait for all tool persistence to finish before writing final state
492	        await persistQueue.catch(console.error);
493	
494	        // Persist final content + reasoning + model + usage to the assistant message
495	        // BEFORE the terminal event triggers fetchAndReplaceMessages.
496	        const updateValue: Record<string, any> = {};
497	        if (accumulatedContent) updateValue.content = accumulatedContent;
498	        if (accumulatedReasoning) updateValue.reasoning = { content: accumulatedReasoning };
499	        if (lastModel) updateValue.model = lastModel;
500	        if (accumulatedUsage.input_tokens + accumulatedUsage.output_tokens > 0) {
501	          updateValue.metadata = {
502	            totalInputTokens:
503	              accumulatedUsage.input_tokens +
504	              accumulatedUsage.cache_creation_input_tokens +
505	              accumulatedUsage.cache_read_input_tokens,
506	            totalOutputTokens: accumulatedUsage.output_tokens,
507	            totalTokens:
508	              accumulatedUsage.input_tokens +
509	              accumulatedUsage.output_tokens +
510	              accumulatedUsage.cache_creation_input_tokens +
511	              accumulatedUsage.cache_read_input_tokens,
512	          };
513	        }
514	
515	        if (Object.keys(updateValue).length > 0) {
516	          await messageService
517	            .updateMessage(currentAssistantMessageId, updateValue, {
518	              agentId: context.agentId,
519	              topicId: context.topicId,
520	            })
521	            .catch(console.error);
522	        }
523	
524	        // NOW forward the deferred terminal event — handler will fetchAndReplaceMessages
525	        // and pick up the final persisted state.
526	        const terminal = deferredTerminalEvent ?? {
527	          data: {},
528	          stepIndex: 0,
529	          timestamp: Date.now(),
530	          type: 'agent_runtime_end' as const,
531	        };
532	        eventHandler(toStreamEvent(terminal, operationId));
533	      },
534	
535	      onError: async (error) => {
536	        if (completed) return;
537	        completed = true;
538	
539	        await persistQueue.catch(console.error);
540	
541	        if (accumulatedContent) {
542	          await messageService
543	            .updateMessage(
544	              currentAssistantMessageId,
545	              { content: accumulatedContent },
546	              {
547	                agentId: context.agentId,
548	                topicId: context.topicId,
549	              },
550	            )
551	            .catch(console.error);
552	        }
553	
554	        eventHandler(
555	          toStreamEvent(
556	            {
557	              data: { error, message: error },
558	              stepIndex: 0,
559	              timestamp: Date.now(),
560	              type: 'error',
561	            },
562	            operationId,
563	          ),
564	        );
565	      },
566	    });
567	
568	    // Send the prompt — blocks until process exits
569	    await heterogeneousAgentService.sendPrompt(agentSessionId, message, imageList);
570	
571	    // Store agent session ID for multi-turn resume
572	    const sessionInfo = await heterogeneousAgentService
573	      .getSessionInfo(agentSessionId)
574	      .catch(() => null);
575	    if (sessionInfo?.agentSessionId && context.topicId) {
576	      // TODO: persist to topic.metadata for cross-restart resume
577	      // For now, agent session ID is only in memory (HeterogeneousAgentCtr stores it)
578	    }
579	  } catch (error) {
580	    if (!completed) {
581	      completed = true;
582	      const errorMsg = error instanceof Error ? error.message : 'Agent execution failed';
583	      eventHandler(
584	        toStreamEvent(
585	          {
586	            data: { error: errorMsg, message: errorMsg },
587	            stepIndex: 0,
588	            timestamp: Date.now(),
589	            type: 'error',
590	          },
591	          operationId,
592	        ),
593	      );
594	    }
595	  } finally {
596	    unsubscribe?.();
597	    if (agentSessionId) {
598	      heterogeneousAgentService.stopSession(agentSessionId).catch(() => {});
599	    }
600	  }
601	};
