1	import type {
2	  AgentStreamEvent,
3	  StepCompleteData,
4	  StreamChunkData,
5	  StreamStartData,
6	  ToolExecuteData,
7	} from '@lobechat/agent-gateway-client';
8	import type { ConversationContext } from '@lobechat/types';
9	
10	import { messageService } from '@/services/message';
11	import type { ChatStore } from '@/store/chat/store';
12	
13	/**
14	 * Fetch messages from DB and replace them in the chat store's dbMessagesMap.
15	 * This updates the ConversationArea component via React subscription:
16	 *   dbMessagesMap → ConversationArea (messages prop) → ConversationStore → UI
17	 */
18	const fetchAndReplaceMessages = async (get: () => ChatStore, context: ConversationContext) => {
19	  const messages = await messageService.getMessages(context);
20	  get().replaceMessages(messages, { context });
21	};
22	
23	/**
24	 * Creates a handler function that processes Agent Gateway events
25	 * and maps them to the chat store's message update actions.
26	 *
27	 * Supports multi-step agent execution (LLM → tool calls → next LLM → ...)
28	 * using a hybrid approach:
29	 * - Current LLM step: real-time streaming via stream_chunk
30	 * - Step transitions: fetchAndReplaceMessages from DB at stream_start / tool_end / step_complete
31	 *
32	 * The handler queues incoming events and processes them sequentially,
33	 * ensuring that stream_chunk waits for stream_start's DB fetch to resolve
34	 * before dispatching updates.
35	 */
36	export const createGatewayEventHandler = (
37	  get: () => ChatStore,
38	  params: {
39	    assistantMessageId: string;
40	    context: ConversationContext;
41	    /**
42	     * Server-side operation id — used to look up the `AgentStreamClient` in
43	     * `gatewayConnections` so we can `sendToolResult` back over the same WS.
44	     * Defaults to `operationId` when the caller does not distinguish the two.
45	     */
46	    gatewayOperationId?: string;
47	    operationId: string;
48	  },
49	) => {
50	  const { context, operationId } = params;
51	  const gatewayOperationId = params.gatewayOperationId ?? operationId;
52	
53	  // Dispatch context — ensures internal_dispatchMessage resolves the correct messageMapKey
54	  const dispatchContext = { operationId };
55	
56	  // Mutable — switches to new assistant message ID on each stream_start
57	  let currentAssistantMessageId = params.assistantMessageId;
58	
59	  // Accumulated content from stream chunks (reset on each stream_start)
60	  let accumulatedContent = '';
61	  let accumulatedReasoning = '';
62	
63	  // Sequential processing queue — ensures stream_chunk waits for stream_start's fetch
64	  let processingChain: Promise<void> = Promise.resolve();
65	
66	  const enqueue = (fn: () => Promise<void> | void): void => {
67	    processingChain = processingChain.then(fn, fn);
68	  };
69	
70	  return (event: AgentStreamEvent) => {
71	    switch (event.type) {
72	      case 'stream_start': {
73	        enqueue(async () => {
74	          const data = event.data as StreamStartData | undefined;
75	
76	          const newAssistantMessageId = data?.assistantMessage?.id;
77	
78	          // Switch to the new assistant message created by the server for this step
79	          if (newAssistantMessageId) {
80	            currentAssistantMessageId = newAssistantMessageId;
81	            // Associate the new message with the operation so UI shows generating state
82	            get().associateMessageWithOperation(currentAssistantMessageId, operationId);
83	          }
84	
85	          // Reset accumulators for the new stream
86	          accumulatedContent = '';
87	          accumulatedReasoning = '';
88	
89	          // Fetch from DB so the new message exists in dbMessagesMap before chunks arrive
90	          await fetchAndReplaceMessages(get, context).catch(console.error);
91	        });
92	        break;
93	      }
94	
95	      case 'stream_chunk': {
96	        enqueue(() => {
97	          const data = event.data as StreamChunkData | undefined;
98	          if (!data) return;
99	
100	          if (data.chunkType === 'text' && data.content) {
101	            accumulatedContent += data.content;
102	            get().internal_dispatchMessage(
103	              {
104	                id: currentAssistantMessageId,
105	                type: 'updateMessage',
106	                value: { content: accumulatedContent },
107	              },
108	              dispatchContext,
109	            );
110	          }
111	
112	          if (data.chunkType === 'reasoning' && data.reasoning) {
113	            accumulatedReasoning += data.reasoning;
114	            get().internal_dispatchMessage(
115	              {
116	                id: currentAssistantMessageId,
117	                type: 'updateMessage',
118	                value: { reasoning: { content: accumulatedReasoning } },
119	              },
120	              dispatchContext,
121	            );
122	          }
123	
124	          if (data.chunkType === 'tools_calling' && data.toolsCalling) {
125	            get().internal_dispatchMessage(
126	              {
127	                id: currentAssistantMessageId,
128	                type: 'updateMessage',
129	                value: { tools: data.toolsCalling },
130	              },
131	              dispatchContext,
132	            );
133	
134	            // Drive tool calling animation
135	            get().internal_toggleToolCallingStreaming(
136	              currentAssistantMessageId,
137	              data.toolsCalling.map(() => true),
138	            );
139	
140	            // If the server attached a `toolMessageIds` map, it has persisted
141	            // pending tool messages (human approval path). Fetch the latest
142	            // messages so ApprovalActions can read them by id instead of
143	            // waiting for `agent_runtime_end` (which won't fire while paused
144	            // in `waiting_for_human`).
145	            if ((data as any).toolMessageIds) {
146	              fetchAndReplaceMessages(get, context).catch(console.error);
147	            }
148	          }
149	        });
150	        break;
151	      }
152	
153	      case 'stream_end': {
154	        enqueue(() => {
155	          // Only clear tool calling streaming — keep message loading active
156	          // until agent_runtime_end so users don't think the session ended
157	          // during tool execution gaps between steps
158	          get().internal_toggleToolCallingStreaming(currentAssistantMessageId, undefined);
159	        });
160	        break;
161	      }
162	
163	      case 'tool_start': {
164	        // Server creates tool messages in DB.
165	        // Loading is already active from stream_start (not cleared by stream_end).
166	        break;
167	      }
168	
169	      case 'tool_execute': {
170	        // Fire-and-forget: the client-side tool may take a long time, and we
171	        // must keep processing other events (stream_chunk, tool_end, etc.) on
172	        // the same WebSocket. `internal_executeClientTool` guarantees it never
173	        // throws and always sends exactly one `tool_result` back.
174	        //
175	        // Use `gatewayOperationId` (server-side id, the key under
176	        // `gatewayConnections`) so the action can look up the WS to reply on
177	        // — NOT the local `operationId` used for `dispatchContext`.
178	        const data = event.data as ToolExecuteData | undefined;
179	        if (!data) break;
180	        void get().internal_executeClientTool(data, { operationId: gatewayOperationId });
181	        break;
182	      }
183	
184	      case 'tool_end': {
185	        enqueue(async () => {
186	          await fetchAndReplaceMessages(get, context).catch(console.error);
187	        });
188	        break;
189	      }
190	
191	      case 'step_complete': {
192	        const data = event.data as StepCompleteData | undefined;
193	
194	        // Refresh on execution_complete to ensure final step state is consistent
195	        if (data?.phase === 'execution_complete') {
196	          enqueue(async () => {
197	            await fetchAndReplaceMessages(get, context).catch(console.error);
198	          });
199	        }
200	        break;
201	      }
202	
203	      case 'agent_runtime_end': {
204	        enqueue(async () => {
205	          get().internal_toggleToolCallingStreaming(currentAssistantMessageId, undefined);
206	          get().completeOperation(operationId);
207	          await fetchAndReplaceMessages(get, context).catch(console.error);
208	        });
209	        break;
210	      }
211	
212	      case 'error': {
213	        enqueue(async () => {
214	          const errorMsg = event.data?.message || event.data?.error || 'Unknown error';
215	
216	          get().internal_toggleToolCallingStreaming(currentAssistantMessageId, undefined);
217	          get().completeOperation(operationId);
218	
219	          // Fetch from DB first — the server may have persisted a richer error
220	          // detail into the message already.
221	          await fetchAndReplaceMessages(get, context).catch(console.error);
222	
223	          // Then overlay the inline error. This ensures the UI always shows the
224	          // error even if the server hasn't persisted it into the message yet
225	          // (the DB fetch would have returned a message with no error field).
226	          get().internal_dispatchMessage(
227	            {
228	              id: currentAssistantMessageId,
229	              type: 'updateMessage',
230	              value: {
231	                error: { body: { message: errorMsg }, type: 'AgentRuntimeError' },
232	              },
233	            },
234	            dispatchContext,
235	          );
236	        });
237	        break;
238	      }
239	    }
240	  };
241	};
