1	import {
2	  type ChatImageItem,
3	  type ChatToolPayload,
4	  type MessageContentPart,
5	  type MessageToolCall,
6	} from '@lobechat/types';
7	import { serializePartsForStorage } from '@lobechat/utils';
8	import debug from 'debug';
9	import { throttle } from 'es-toolkit/compat';
10	import pMap from 'p-map';
11	
12	import { cleanSpeakerTag } from '../utils/cleanSpeakerTag';
13	import {
14	  type FinishData,
15	  type GroundingData,
16	  type ReasoningState,
17	  type StreamChunk,
18	  type StreamingCallbacks,
19	  type StreamingContext,
20	  type StreamingResult,
21	} from './types/streaming';
22	
23	const log = debug('lobe-store:streaming-handler');
24	
25	/**
26	 * Streaming message handler
27	 *
28	 * Encapsulates all state and logic for streaming message processing, including:
29	 * - Text content accumulation
30	 * - Reasoning content processing
31	 * - Multimodal content processing
32	 * - Tool calls processing
33	 * - Image upload management
34	 *
35	 * @example
36	 * ```typescript
37	 * const handler = new StreamingHandler(context, callbacks);
38	 *
39	 * // During streaming
40	 * handler.handleChunk(chunk);
41	 *
42	 * // When streaming completes
43	 * const result = await handler.handleFinish(finishData);
44	 * ```
45	 */
46	export class StreamingHandler {
47	  // ========== Text state ==========
48	  private output = '';
49	
50	  // ========== Reasoning state ==========
51	  private thinkingContent = '';
52	  private thinkingStartAt?: number;
53	  private thinkingDuration?: number;
54	  private reasoningOperationId?: string;
55	  private reasoningParts: MessageContentPart[] = [];
56	
57	  // ========== Multimodal state ==========
58	  private contentParts: MessageContentPart[] = [];
59	
60	  // ========== Tool call state ==========
61	  private isFunctionCall = false;
62	  private tools?: ChatToolPayload[];
63	
64	  // ========== Image upload state ==========
65	  private uploadTasks = new Map<string, Promise<{ id?: string; url?: string }>>();
66	  private contentImageUploads = new Map<number, Promise<string>>();
67	  private reasoningImageUploads = new Map<number, Promise<string>>();
68	
69	  // ========== Other state ==========
70	  private msgTraceId?: string;
71	  private finishType?: string;
72	
73	  // ========== Throttled updates ==========
74	  private throttledUpdateToolCalls: ReturnType<typeof throttle>;
75	
76	  constructor(
77	    private context: StreamingContext,
78	    private callbacks: StreamingCallbacks,
79	  ) {
80	    // Initialize throttled tool calls update (max once per 300ms)
81	    this.throttledUpdateToolCalls = throttle(
82	      (toolCalls) => {
83	        const tools = this.callbacks.transformToolCalls(toolCalls);
84	        this.callbacks.onToolCallsUpdate(tools);
85	      },
86	      300,
87	      { leading: true, trailing: true },
88	    );
89	  }
90	
91	  // ==================== Public API ====================
92	
93	  /**
94	   * Handle streaming chunk
95	   */
96	  handleChunk(chunk: StreamChunk): void {
97	    switch (chunk.type) {
98	      case 'text': {
99	        this.handleTextChunk(chunk);
100	        break;
101	      }
102	      case 'reasoning': {
103	        this.handleReasoningChunk(chunk);
104	        break;
105	      }
106	      case 'reasoning_part': {
107	        this.handleReasoningPartChunk(chunk);
108	        break;
109	      }
110	      case 'content_part': {
111	        this.handleContentPartChunk(chunk);
112	        break;
113	      }
114	      case 'tool_calls': {
115	        this.handleToolCallsChunk(chunk);
116	        break;
117	      }
118	      case 'grounding': {
119	        this.handleGroundingChunk(chunk);
120	        break;
121	      }
122	      case 'base64_image': {
123	        this.handleBase64ImageChunk(chunk);
124	        break;
125	      }
126	      case 'stop': {
127	        this.handleStopChunk();
128	        break;
129	      }
130	    }
131	  }
132	
133	  /**
134	   * Handle streaming finish
135	   */
136	  async handleFinish(finishData: FinishData): Promise<StreamingResult> {
137	    // Update traceId
138	    if (finishData.traceId) {
139	      this.msgTraceId = finishData.traceId;
140	    }
141	
142	    // Wait for all image uploads to complete
143	    const finalImages = await this.waitForImageUploads();
144	
145	    // Wait for multimodal image uploads to complete
146	    await this.waitForMultimodalUploads();
147	
148	    // Process final tool calls
149	    this.processFinalToolCalls(finishData.toolCalls);
150	
151	    // Build final result
152	    return this.buildFinalResult(finishData, finalImages);
153	  }
154	
155	  /**
156	   * Get current output content
157	   */
158	  getOutput(): string {
159	    return this.output;
160	  }
161	
162	  /**
163	   * Get reasoning duration
164	   */
165	  getThinkingDuration(): number | undefined {
166	    return this.thinkingDuration;
167	  }
168	
169	  /**
170	   * Check if this is a function call
171	   */
172	  getIsFunctionCall(): boolean {
173	    return this.isFunctionCall;
174	  }
175	
176	  /**
177	   * Get tools
178	   */
179	  getTools(): ChatToolPayload[] | undefined {
180	    return this.tools;
181	  }
182	
183	  /**
184	   * Get trace ID
185	   */
186	  getTraceId(): string | undefined {
187	    return this.msgTraceId;
188	  }
189	
190	  /**
191	   * Get finish type
192	   */
193	  getFinishType(): string | undefined {
194	    return this.finishType;
195	  }
196	
197	  // ==================== Chunk handling methods ====================
198	
199	  private handleTextChunk(chunk: { text: string; type: 'text' }): void {
200	    this.output += chunk.text;
201	
202	    // Clean speaker tag that may be reproduced by model in group chat
203	    this.output = cleanSpeakerTag(this.output);
204	
205	    // End reasoning timing
206	    this.endReasoningIfNeeded();
207	
208	    log(
209	      '[text stream] messageId=%s, output length=%d, operationId=%s',
210	      this.context.messageId,
211	      this.output.length,
212	      this.context.operationId,
213	    );
214	
215	    // Notify update
216	    this.callbacks.onContentUpdate(this.output, this.buildReasoningState());
217	  }
218	
219	  private handleReasoningChunk(chunk: { text: string; type: 'reasoning' }): void {
220	    // Start reasoning timing
221	    this.startReasoningIfNeeded();
222	
223	    this.thinkingContent += chunk.text;
224	
225	    this.callbacks.onReasoningUpdate({ content: this.thinkingContent });
226	  }
227	
228	  private handleReasoningPartChunk(chunk: {
229	    content: string;
230	    mimeType?: string;
231	    partType: 'text' | 'image';
232	    type: 'reasoning_part';
233	  }): void {
234	    // Start reasoning timing
235	    this.startReasoningIfNeeded();
236	
237	    if (chunk.partType === 'text') {
238	      this.appendTextToReasoningParts(chunk.content);
239	      this.thinkingContent += chunk.content;
240	    } else if (chunk.partType === 'image' && chunk.mimeType) {
241	      this.appendImageToReasoningParts(chunk.content, chunk.mimeType);
242	    }
243	
244	    // Notify update
245	    const hasImages = this.reasoningParts.some((p) => p.type === 'image');
246	    this.callbacks.onReasoningUpdate(
247	      hasImages
248	        ? { isMultimodal: true, tempDisplayContent: this.reasoningParts }
249	        : { content: this.thinkingContent },
250	    );
251	  }
252	
253	  private handleContentPartChunk(chunk: {
254	    content: string;
255	    mimeType?: string;
256	    partType: 'text' | 'image';
257	    type: 'content_part';
258	  }): void {
259	    // End reasoning timing
260	    this.endReasoningIfNeeded();
261	
262	    if (chunk.partType === 'text') {
263	      this.appendTextToContentParts(chunk.content);
264	      this.output += chunk.content;
265	
266	      // Clean speaker tag
267	      this.output = cleanSpeakerTag(this.output);
268	    } else if (chunk.partType === 'image' && chunk.mimeType) {
269	      this.appendImageToContentParts(chunk.content, chunk.mimeType);
270	    }
271	
272	    // Notify update
273	    this.notifyContentPartUpdate();
274	  }
275	
276	  private handleToolCallsChunk(chunk: {
277	    isAnimationActives?: boolean[];
278	    tool_calls: MessageToolCall[];
279	    type: 'tool_calls';
280	  }): void {
281	    this.isFunctionCall = true;
282	    this.callbacks.toggleToolCallingStreaming(this.context.messageId, chunk.isAnimationActives);
283	    this.throttledUpdateToolCalls(chunk.tool_calls);
284	
285	    // End reasoning timing
286	    this.endReasoningIfNeeded();
287	  }
288	
