403	  private notifyContentPartUpdate(): void {
404	    const hasContentImages = this.contentParts.some((p) => p.type === 'image');
405	    const hasReasoningImages = this.reasoningParts.some((p) => p.type === 'image');
406	
407	    this.callbacks.onContentUpdate(
408	      this.output,
409	      hasReasoningImages
410	        ? {
411	            duration: this.thinkingDuration,
412	            isMultimodal: true,
413	            tempDisplayContent: this.reasoningParts,
414	          }
415	        : this.thinkingContent
416	          ? { content: this.thinkingContent, duration: this.thinkingDuration }
417	          : undefined,
418	      hasContentImages
419	        ? {
420	            isMultimodal: true,
421	            tempDisplayContent: serializePartsForStorage(this.contentParts),
422	          }
423	        : undefined,
424	    );
