432	  private async waitForImageUploads(): Promise<ChatImageItem[]> {
433	    if (this.uploadTasks.size === 0) return [];
434	
435	    try {
436	      const results = await pMap(Array.from(this.uploadTasks.values()), (task) => task, {
437	        concurrency: 5,
438	      });
439	      return results.filter((i) => !!i.url) as ChatImageItem[];
440	    } catch (error) {
