446	  private async waitForMultimodalUploads(): Promise<void> {
447	    await Promise.allSettled([
448	      ...Array.from(this.contentImageUploads.values()),
449	      ...Array.from(this.reasoningImageUploads.values()),
450	    ]);
451	  }
452	
453	  private processFinalToolCalls(toolCalls?: MessageToolCall[]): void {
454	    if (!toolCalls?.length) return;
455	
456	    this.throttledUpdateToolCalls.flush();
457	    this.callbacks.toggleToolCallingStreaming(this.context.messageId, undefined);
458	
459	    const processedToolCalls = toolCalls.map((item) => ({
460	      ...item,
461	      function: {
462	        ...item.function,
463	        arguments: item.function.arguments || '{}',
464	      },
465	    }));
466	
467	    this.tools = this.callbacks.transformToolCalls(processedToolCalls);
468	    this.isFunctionCall = true;
469	  }
470	
471	  private buildFinalResult(finishData: FinishData, finalImages: ChatImageItem[]): StreamingResult {
472	    const hasContentImages = this.contentParts.some((p) => p.type === 'image');
473	    const hasReasoningImages = this.reasoningParts.some((p) => p.type === 'image');
474	
475	    // Determine final content
476	    const finalContent = hasContentImages
477	      ? serializePartsForStorage(this.contentParts)
478	      : this.output;
479	
480	    // Determine final reasoning content
481	    const finalDuration =
482	      this.thinkingDuration && !isNaN(this.thinkingDuration) ? this.thinkingDuration : undefined;
483	
484	    // Get signature from finishData.reasoning (provided by backend in onFinish)
485	    const reasoningSignature = finishData.reasoning?.signature;
486	
487	    let finalReasoning: ReasoningState | undefined;
488	    if (hasReasoningImages) {
489	      finalReasoning = {
490	        content: serializePartsForStorage(this.reasoningParts),
491	        duration: finalDuration,
492	        isMultimodal: true,
493	        signature: reasoningSignature,
494	      };
495	    } else if (this.thinkingContent) {
496	      finalReasoning = {
497	        content: this.thinkingContent,
498	        duration: finalDuration,
499	        signature: reasoningSignature,
500	      };
501	    } else if (finishData.reasoning?.content) {
502	      finalReasoning = {
503	        ...finishData.reasoning,
504	        duration: finalDuration,
505	      };
506	    }
507	
508	    this.finishType = finishData.type;
509	
510	    log(
511	      '[handleFinish] messageId=%s, finishType=%s, operationId=%s',
512	      this.context.messageId,
513	      finishData.type,
514	      this.context.operationId,
515	    );
516	
517	    return {
518	      content: finalContent,
519	      finishType: finishData.type,
520	      isFunctionCall: this.isFunctionCall,
521	      metadata: {
522	        finishType: finishData.type,
523	        imageList: finalImages.length > 0 ? finalImages : undefined,
524	        isMultimodal: hasContentImages || undefined,
525	        performance: finishData.speed,
526	        reasoning: finalReasoning,
527	        search:
528	          finishData.grounding?.citations?.length || finishData.grounding?.imageResults?.length
529	            ? finishData.grounding
530	            : undefined,
531	        usage: finishData.usage,
532	      },
533	      toolCalls: finishData.toolCalls,
534	      tools: this.tools,
535	      traceId: this.msgTraceId,
536	      usage: finishData.usage,
537	    };
538	  }
539	}
