75	
76	  constructor(
77	    private context: StreamingContext,
78	    private callbacks: StreamingCallbacks,
79	  ) {
80	    // Initialize throttled tool calls update (max once per 300ms)
81	    this.throttledUpdateToolCalls = throttle(
82	      (toolCalls) => {
83	        const tools = this.callbacks.transformToolCalls(toolCalls);
84	        this.callbacks.onToolCallsUpdate(tools);
85	      },
86	      300,
87	      { leading: true, trailing: true },
