1	import { type ToolExecuteData, type ToolResultMessage } from '@lobechat/agent-gateway-client';
2	import { type BuiltinToolContext } from '@lobechat/types';
3	import debug from 'debug';
4	import { produce } from 'immer';
5	
6	import { mcpService } from '@/services/mcp';
7	import { type ChatStore } from '@/store/chat/store';
8	import { hasExecutor, invokeExecutor } from '@/store/tool/slices/builtin/executors';
9	import { type StoreSetter } from '@/store/types';
10	import { safeParseJSON } from '@/utils/safeParseJSON';
11	
12	const log = debug('lobe-store:client-tool-execution');
13	
14	type Setter = StoreSetter<ChatStore>;
15	
16	/**
17	 * Executes a Gateway `tool_execute` request locally and always returns a
18	 * `tool_result` — even on parse failure, missing executor, or thrown error.
19	 *
20	 * Never let the server-side BLPOP time out: the contract is that every
21	 * `tool_execute` produces exactly one `tool_result` back over the same WS.
22	 */
23	export class ClientToolExecutionActionImpl {
24	  readonly #get: () => ChatStore;
25	  readonly #set: Setter;
26	
27	  constructor(set: Setter, get: () => ChatStore, _api?: unknown) {
28	    void _api;
29	    this.#set = set;
30	    this.#get = get;
31	  }
32	
33	  internal_executeClientTool = async (
34	    data: ToolExecuteData,
35	    context: { operationId: string },
36	  ): Promise<void> => {
37	    const { toolCallId, identifier, apiName, arguments: argsString } = data;
38	    const { operationId } = context;
39	
40	    log(
41	      '[internal_executeClientTool] start toolCallId=%s identifier=%s apiName=%s op=%s',
42	      toolCallId,
43	      identifier,
44	      apiName,
45	      operationId,
46	    );
47	
48	    this.#setPending(toolCallId, true);
49	
50	    // Captured once; must be the SAME connection that received the execute request.
51	    const conn = this.#get().gatewayConnections[operationId];
52	
53	    const send = (payload: Omit<ToolResultMessage, 'type'>): void => {
54	      this.#setPending(toolCallId, false);
55	      if (!conn) {
56	        log(
57	          '[internal_executeClientTool] no gateway connection for op=%s toolCallId=%s — server will timeout',
58	          operationId,
59	          toolCallId,
60	        );
61	        return;
62	      }
63	      const ok = conn.client.sendToolResult(payload);
64	      if (!ok) {
65	        log(
66	          '[internal_executeClientTool] sendToolResult returned false (socket closed) for toolCallId=%s',
67	          toolCallId,
68	        );
69	      }
70	    };
71	
72	    // ─── Parse arguments ───
73	    let params: any = {};
74	    if (argsString) {
75	      const parsed = safeParseJSON(argsString);
76	      if (parsed === undefined) {
77	        send({
78	          content: null,
79	          error: {
80	            message: `Failed to parse tool arguments: ${argsString.slice(0, 200)}`,
81	            type: 'arguments_parse_error',
82	          },
83	          success: false,
84	          toolCallId,
85	        });
86	        return;
87	      }
88	      params = parsed ?? {};
89	    }
90	
91	    try {
92	      // ─── Builtin dispatch (via registry) ───
93	      if (hasExecutor(identifier, apiName)) {
94	        const operation = this.#get().operations[operationId];
95	        const ctx: BuiltinToolContext = {
96	          agentId: operation?.context?.agentId,
97	          groupId: operation?.context?.groupId,
98	          // Gateway-side tool messages are persisted on the server; the client
99	          // has no local message id, so reuse toolCallId as the context key.
100	          messageId: toolCallId,
101	          operationId,
102	          signal: operation?.abortController?.signal,
103	          topicId: operation?.context?.topicId ?? undefined,
104	        };
105	
106	        const result = await invokeExecutor(identifier, apiName, params, ctx);
107	
108	        if (result.error) {
109	          send({
110	            content: result.content ?? result.error.message ?? null,
111	            error: { message: result.error.message, type: result.error.type },
112	            state: result.state,
113	            success: false,
114	            toolCallId,
115	          });
116	        } else {
117	          send({
118	            content: result.content ?? null,
119	            state: result.state,
120	            success: !!result.success,
121	            toolCallId,
122	          });
123	        }
124	        return;
125	      }
126	
127	      // ─── MCP fallback — unified dispatch, mirrors invokeMCPTypePlugin shape ───
128	      const operation = this.#get().operations[operationId];
129	      const mcpResult = await mcpService
130	        .invokeMcpToolCall(
131	          {
132	            apiName,
133	            arguments: argsString,
134	            id: toolCallId,
135	            identifier,
136	            type: 'default',
137	          },
138	          {
139	            signal: operation?.abortController?.signal,
140	            topicId: operation?.context?.topicId ?? undefined,
141	          },
142	        )
143	        .catch((err) => {
144	          log(
145	            '[internal_executeClientTool] mcp invoke threw for %s/%s: %O',
146	            identifier,
147	            apiName,
148	            err,
149	          );
150	          return undefined;

