1	import { getBuiltinRender } from '@lobechat/builtin-tools/renders';
2	import { getBuiltinStreaming } from '@lobechat/builtin-tools/streamings';
3	import { LOADING_FLAT } from '@lobechat/const';
4	import { type ChatToolResult, type ToolIntervention } from '@lobechat/types';
5	import { AccordionItem, Flexbox, Skeleton } from '@lobehub/ui';
6	import { Divider } from 'antd';
7	import { memo, useEffect, useState } from 'react';
8	
9	import SafeBoundary from '@/components/ErrorBoundary';
10	import dynamic from '@/libs/next/dynamic';
11	import { useChatStore } from '@/store/chat';
12	import { operationSelectors } from '@/store/chat/slices/operation/selectors';
13	import { useToolStore } from '@/store/tool';
14	import { toolSelectors } from '@/store/tool/selectors';
15	
16	import Actions from './Actions';
17	import Inspectors from './Inspector';
18	
19	const Debug = dynamic(() => import('./Debug'), {
20	  loading: () => <Skeleton.Block active height={300} width={'100%'} />,
21	  ssr: false,
22	});
23	
24	const Detail = dynamic(() => import('./Detail'), {
25	  loading: () => <Skeleton.Block active height={120} width={'100%'} />,
26	  ssr: false,
27	});
28	
29	export interface GroupToolProps {
30	  apiName: string;
31	  arguments?: string;
32	  assistantMessageId: string;
33	  disableEditing?: boolean;
34	  id: string;
35	  identifier: string;
36	  intervention?: ToolIntervention;
37	  result?: ChatToolResult;
38	  toolMessageId?: string;
39	  type?: string;
40	}
41	
42	const Tool = memo<GroupToolProps>(
43	  ({
44	    arguments: requestArgs,
45	    apiName,
46	    assistantMessageId,
47	    disableEditing,
48	    id,
49	    intervention,
50	    identifier,
51	    result,
52	    type,
53	    toolMessageId,
54	  }) => {
55	    // Get renderDisplayControl from manifest
56	    const renderDisplayControl = useToolStore(
57	      toolSelectors.getRenderDisplayControl(identifier, apiName),
58	    );
59	    const [showDebug, setShowDebug] = useState(false);
60	    const [showToolRender, setShowToolRender] = useState(false);
61	    // Controls switching between custom render and fallback ArgumentRender
62	    const [showCustomToolRender, setShowCustomToolRender] = useState(true);
63	
64	    const isPending = intervention?.status === 'pending';
65	    const isReject = intervention?.status === 'rejected';
66	    const isAbort = intervention?.status === 'aborted';
67	    const needExpand = renderDisplayControl !== 'collapsed' || isPending;
68	    const isAlwaysExpand = renderDisplayControl === 'alwaysExpand';
69	
70	    let isArgumentsStreaming = false;
71	    try {
72	      JSON.parse(requestArgs || '{}');
73	    } catch {
74	      isArgumentsStreaming = true;
75	    }
76	
77	    const hasStreamingRenderer = !!getBuiltinStreaming(identifier, apiName);
78	    const forceShowStreamingRender = isArgumentsStreaming && hasStreamingRenderer;
79	
80	    // Get precise tool calling state from operation
81	    const isToolCallingFromOperation = useChatStore(
82	      operationSelectors.isMessageInToolCalling(assistantMessageId),
83	    );
84	
85	    // Fallback: arguments completed but no final result yet
86	    const hasError = !!result?.error;
87	    const isToolCallingFallback =
88	      !hasError &&
89	      !isArgumentsStreaming &&
90	      (!result || result.content === LOADING_FLAT || !result.content);
91	    const isToolCalling = isToolCallingFromOperation || isToolCallingFallback;
92	
93	    const hasCustomRender = !!getBuiltinRender(identifier, apiName);
94	    // Only allow toggle when has custom render and not in pending/reject/abort state
95	    const canToggleCustomToolRender = hasCustomRender && !isPending && !isReject && !isAbort;
96	
97	    // Handle expand state changes
98	    const handleExpand = (expand?: boolean) => {
99	      // Block collapse action when alwaysExpand is set
100	      if (isAlwaysExpand && expand === false) {
101	        return;
102	      }
103	      // When collapsing, also turn off debug mode so the accordion can actually collapse
104	      if (expand === false) {
105	        setShowDebug(false);
106	      }
107	      setShowToolRender(!!expand);
108	    };
109	
110	    useEffect(() => {
111	      if (needExpand) {
112	        setTimeout(() => handleExpand(true), 100);
113	      }
114	    }, [needExpand]);
115	
116	    const isToolDetailExpand = forceShowStreamingRender || showToolRender || showDebug;
117	
118	    return (
119	      <AccordionItem
120	        expand={isToolDetailExpand}
121	        hideIndicator={isAlwaysExpand}
122	        itemKey={id}
123	        paddingBlock={4}
124	        paddingInline={4}
125	        action={
126	          !disableEditing && (
127	            <Actions
128	              assistantMessageId={assistantMessageId}
129	              canToggleCustomToolRender={canToggleCustomToolRender}
130	              identifier={identifier}
131	              setShowCustomToolRender={setShowCustomToolRender}
132	              setShowDebug={setShowDebug}
133	              showCustomToolRender={showCustomToolRender}
134	              showDebug={showDebug}
135	            />
136	          )
137	        }
138	        title={
139	          <Inspectors
140	            apiName={apiName}
141	            arguments={requestArgs}
142	            identifier={identifier}
143	            intervention={intervention}
144	            isArgumentsStreaming={isArgumentsStreaming}
145	            result={result}
146	          />
147	        }
148	        onExpandChange={handleExpand}
149	      >
150	        <Flexbox gap={8} paddingBlock={8}>
151	          {showDebug && (
152	            <Debug
153	              apiName={apiName}
154	              identifier={identifier}
155	              intervention={intervention}
156	              requestArgs={requestArgs}
157	              result={result}
158	              toolCallId={id}
159	              type={type}
160	            />
161	          )}
162	          <SafeBoundary alertTitle={`${identifier} / ${apiName}`} variant="alert">
163	            <Detail
164	              apiName={apiName}
165	              arguments={requestArgs}
166	              disableEditing={disableEditing}
167	              identifier={identifier}
168	              intervention={intervention}
169	              isArgumentsStreaming={isArgumentsStreaming}
170	              isToolCalling={isToolCalling}
171	              messageId={assistantMessageId}
172	              result={result}
173	              showCustomToolRender={showCustomToolRender}
174	              toolCallId={id}
175	              toolMessageId={toolMessageId}
176	              type={type}
177	            />
178	          </SafeBoundary>
179	          <Divider dashed style={{ marginBottom: 0, marginTop: 8 }} />
180	        </Flexbox>
181	      </AccordionItem>
182	    );
183	  },
184	);
185	
186	Tool.displayName = 'GroupTool';
187	
188	export default Tool;
189

