94	    // Only allow toggle when has custom render and not in pending/reject/abort state
95	    const canToggleCustomToolRender = hasCustomRender && !isPending && !isReject && !isAbort;
96	
97	    // Handle expand state changes
98	    const handleExpand = (expand?: boolean) => {
99	      // Block collapse action when alwaysExpand is set
100	      if (isAlwaysExpand && expand === false) {
101	        return;
102	      }
103	      // When collapsing, also turn off debug mode so the accordion can actually collapse
104	      if (expand === false) {
105	        setShowDebug(false);
106	      }
107	      setShowToolRender(!!expand);
108	    };
109	
110	    useEffect(() => {
111	      if (needExpand) {
112	        setTimeout(() => handleExpand(true), 100);
113	      }
114	    }, [needExpand]);
115	
116	    const isToolDetailExpand = forceShowStreamingRender || showToolRender || showDebug;
117	
118	    return (
119	      <AccordionItem
120	        expand={isToolDetailExpand}
121	        hideIndicator={isAlwaysExpand}
122	        itemKey={id}
123	        paddingBlock={4}
124	        paddingInline={4}
125	        action={
126	          !disableEditing && (
127	            <Actions
128	              assistantMessageId={assistantMessageId}
129	              canToggleCustomToolRender={canToggleCustomToolRender}
130	              identifier={identifier}
131	              setShowCustomToolRender={setShowCustomToolRender}
132	              setShowDebug={setShowDebug}
133	              showCustomToolRender={showCustomToolRender}
134	              showDebug={showDebug}
135	            />
136	          )
137	        }
138	        title={
139	          <Inspectors
140	            apiName={apiName}
141	            arguments={requestArgs}
142	            identifier={identifier}
143	            intervention={intervention}
144	            isArgumentsStreaming={isArgumentsStreaming}
145	            result={result}
146	          />
147	        }
148	        onExpandChange={handleExpand}
149	      >
150	        <Flexbox gap={8} paddingBlock={8}>
151	          {showDebug && (
152	            <Debug
153	              apiName={apiName}
154	              identifier={identifier}
155	              intervention={intervention}
156	              requestArgs={requestArgs}
157	              result={result}
158	              toolCallId={id}
159	              type={type}
160	            />
161	          )}
162	          <SafeBoundary alertTitle={`${identifier} / ${apiName}`} variant="alert">
163	            <Detail
164	              apiName={apiName}
165	              arguments={requestArgs}
166	              disableEditing={disableEditing}
167	              identifier={identifier}
168	              intervention={intervention}
169	              isArgumentsStreaming={isArgumentsStreaming}
170	              isToolCalling={isToolCalling}
171	              messageId={assistantMessageId}
172	              result={result}
173	              showCustomToolRender={showCustomToolRender}
174	              toolCallId={id}
175	              toolMessageId={toolMessageId}
176	              type={type}
177	            />
178	          </SafeBoundary>
179	          <Divider dashed style={{ marginBottom: 0, marginTop: 8 }} />
180	        </Flexbox>
181	      </AccordionItem>
182	    );
183	  },
184	);
185	
186	Tool.displayName = 'GroupTool';
187	
188	export default Tool;
