332	
333	        {/* Processing or Completed view */}
334	        {isProcessing ? (
335	          <ProcessingView
336	            accumulatedUsage={accumulatedUsage}
337	            messages={messages}
338	            model={model}
339	            provider={provider}
340	            startTime={startTime}
341	            totalToolCalls={totalToolCalls}
342	          />
343	        ) : (
344	          <CompletedView
345	            assistantId={assistantId}
346	            blocks={blocks}
347	            duration={duration}
348	            model={model}
349	            provider={provider}
350	            totalCost={totalCost}
351	            totalTokens={accumulatedUsage.totalTokens}
352	            totalToolCalls={totalToolCalls}
353	          />
354	        )}
355	      </Flexbox>
356	    );
357	  },
358	);
359	
360	TaskMessages.displayName = 'TaskMessages';
361	
362	export default TaskMessages;
