1	import { parse } from '@lobechat/conversation-flow';
2	import { type ConversationContext, type UIChatMessage } from '@lobechat/types';
3	import debug from 'debug';
4	import { type SWRResponse } from 'swr';
5	import { type StateCreator } from 'zustand/vanilla';
6	
7	import { useClientDataSWRWithSync } from '@/libs/swr';
8	import { messageService } from '@/services/message';
9	import { messageMapKey } from '@/store/chat/utils/messageMapKey';
10	
11	import { type Store as ConversationStore } from '../../action';
12	import { type MessageDispatch } from './reducer';
13	import { messagesReducer } from './reducer';
14	import { dataSelectors } from './selectors';
15	
16	const log = debug('lobe-render:features:Conversation');
17	
18	/**
19	 * Data Actions
20	 *
21	 * Handles message fetching based on conversation context.
22	 */
23	export interface DataAction {
24	  /**
25	   * Dispatch message updates for optimistic UI updates
26	   * This method updates the frontend state without persisting to database
27	   */
28	  internal_dispatchMessage: (payload: MessageDispatch) => void;
29	
30	  /**
31	   * Replace all messages with new data
32	   * Used for syncing after database operations (optimistic update pattern)
33	   *
34	   * @param messages - New messages array from database
35	   */
36	  replaceMessages: (messages: UIChatMessage[]) => void;
37	
38	  /**
39	   * Switch message branch by updating the parent's activeBranchIndex
40	   *
41	   * @param messageId - The current message ID (with branch indicator)
42	   * @param branchIndex - The new branch index to switch to
43	   */
44	  switchMessageBranch: (messageId: string, branchIndex: number) => Promise<void>;
45	
46	  /**
47	   * Fetch messages for this conversation using SWR
48	   *
49	   * @param context - Conversation context with sessionId and topicId
50	   * @param skipFetch - When true, SWR key is null and no fetch occurs
51	   */
52	  useFetchMessages: (
53	    context: ConversationContext,
54	    skipFetch?: boolean,
55	  ) => SWRResponse<UIChatMessage[]>;
56	}
57	
58	export const dataSlice: StateCreator<
59	  ConversationStore,
60	  [['zustand/devtools', never]],
61	  [],
62	  DataAction
63	> = (set, get) => ({
64	  internal_dispatchMessage: (payload) => {
65	    const contextKey = messageMapKey(get().context);
66	
67	    log(
68	      '[dispatchMessage] start | contextKey=%s | type=%s | id=%s',
69	      contextKey,
70	      payload.type,
71	      'id' in payload ? payload.id : 'ids' in payload ? payload.ids.join(',') : 'N/A',
72	    );
73	
74	    // Special handling for messageGroup metadata updates
75	    // MessageGroups are not in dbMessages, they're injected during query
76	    if (payload.type === 'updateMessageGroupMetadata') {
77	      const displayMessages = get().displayMessages;
78	      const index = displayMessages.findIndex((m) => m.id === payload.id);
79	      if (index < 0) return;
80	
81	      const newDisplayMessages = [...displayMessages];
82	      newDisplayMessages[index] = {
83	        ...newDisplayMessages[index],
84	        metadata: { ...newDisplayMessages[index].metadata, ...payload.value },
85	      };
86	
87	      set({ displayMessages: newDisplayMessages }, false, {
88	        payload,
89	        type: `dispatchMessage/${payload.type}`,
90	      });
91	      return;
92	    }
93	
94	    const dbMessages = get().dbMessages;
95	
96	    // Apply array-based reducer - preserves message order
97	    const newDbMessages = messagesReducer(dbMessages, payload);
98	
99	    // Check if anything changed
100	    if (newDbMessages === dbMessages) {
101	      log('[dispatchMessage] no change | contextKey=%s', contextKey);
102	      return;
103	    }
104	
105	    // Re-parse for display order and grouping
106	    const { flatList } = parse(newDbMessages);
107	
108	    log(
109	      '[dispatchMessage] updated | contextKey=%s | prevCount=%d | newCount=%d | displayCount=%d',
110	      contextKey,
111	      dbMessages.length,
112	      newDbMessages.length,
113	      flatList.length,
114	    );
115	
116	    set({ dbMessages: newDbMessages, displayMessages: flatList }, false, {
117	      payload,
118	      type: `dispatchMessage/${payload.type}`,
119	    });
120	
121	    // Sync changes to external store (ChatStore)
122	    get().onMessagesChange?.(newDbMessages, get().context);
123	  },
124	
125	  replaceMessages: (messages) => {
126	    const contextKey = messageMapKey(get().context);
127	    const prevDbMessages = get().dbMessages;
128	
129	    // Parse messages using conversation-flow
130	    const { flatList } = parse(messages);
131	
132	    log(
133	      '[replaceMessages] | contextKey=%s | prevCount=%d | newCount=%d | displayCount=%d | messageIds=%o',
134	      contextKey,
135	      prevDbMessages.length,
136	      messages.length,
137	      flatList.length,
138	      messages.slice(0, 5).map((m) => m.id),
139	    );
140	
141	    set({ dbMessages: messages, displayMessages: flatList }, false, 'replaceMessages');
142	
143	    // Sync changes to external store (ChatStore)
144	    get().onMessagesChange?.(messages, get().context);
145	  },
146	
147	  switchMessageBranch: async (messageId, branchIndex) => {
148	    const state = get();
149	
150	    // Get the current message to find its parent
151	    const message = dataSelectors.getDbMessageById(messageId)(state);
152	    if (!message || !message.parentId) return;
153	
154	    // Update the parent's metadata.activeBranchIndex
155	    // because the branch indicator is on the child message,
156	    // but the activeBranchIndex is stored on the parent
157	    await state.updateMessageMetadata(message.parentId, { activeBranchIndex: branchIndex });
158	  },
159	
160	  useFetchMessages: (context, skipFetch) => {
161	    // When skipFetch is true, SWR key is null - no fetch occurs
162	    // This is used when external messages are provided (e.g., creating new thread)
163	    // Also skip fetch when topicId is null (new conversation state) - there's no server data,
164	    // only local optimistic updates. Fetching would return empty array and overwrite local data.
165	    const shouldFetch = !skipFetch && !!context.agentId && !!context.topicId;
166	    const contextKey = messageMapKey(context);
167	
168	    log(
169	      '[useFetchMessages] hook | contextKey=%s | shouldFetch=%s | skipFetch=%s | agentId=%s | topicId=%s',
170	      contextKey,
171	      shouldFetch,
172	      skipFetch,
173	      context.agentId,
174	      context.topicId,
175	    );
176	
177	    return useClientDataSWRWithSync<UIChatMessage[]>(
178	      shouldFetch ? ['CONVERSATION_FETCH_MESSAGES', context] : null,
179	
180	      () => messageService.getMessages(context),
181	      {
182	        onData: (data) => {
183	          if (!data) return;
184	          if (!context.topicId) return;
185	
186	          const prevDbMessages = get().dbMessages;
187	          const storeContextKey = messageMapKey(get().context);
188	
189	          // Parse messages using conversation-flow
190	          const { flatList } = parse(data);
191	
192	          log(
193	            '[useFetchMessages] onData | requestContextKey=%s | storeContextKey=%s | prevCount=%d | fetchedCount=%d | displayCount=%d | messageIds=%o',
194	            contextKey,
195	            storeContextKey,
196	            prevDbMessages.length,
197	            data.length,
198	            flatList.length,
199	            data.slice(0, 5).map((m) => m.id),
200	          );
201	
202	          set({
203	            dbMessages: data,
204	            displayMessages: flatList,
205	            messagesInit: true,
206	          });
207	
208	          // Call onMessagesChange callback with the request context (not current context)
209	          // This ensures data is stored to the correct topic even if user switched topics
210	          get().onMessagesChange?.(data, context);
211	        },
212	      },
213	    );
214	  },
215	});
216

