9	
10	import BubblesLoading from '@/components/BubblesLoading';
11	import SafeBoundary from '@/components/ErrorBoundary';
12	
13	import History from '../components/History';
14	import { useChatItemContextMenu } from '../hooks/useChatItemContextMenu';
15	import { dataSelectors, messageStateSelectors, useConversationStore } from '../store';
16	import AgentCouncilMessage from './AgentCouncil';
17	import AssistantMessage from './Assistant';
18	import AssistantGroupMessage from './AssistantGroup';
19	import CompressedGroupMessage from './CompressedGroup';
20	import GroupTasksMessage from './GroupTasks';
21	import SupervisorMessage from './Supervisor';
22	import TaskMessage from './Task';
23	import TasksMessage from './Tasks';
24	import ToolMessage from './Tool';
25	import UserMessage from './User';
26	
27	const prefixCls = 'ant';
28	
29	const styles = createStaticStyles(({ css }) => ({
30	  loading: css`
31	    opacity: 0.6;
32	  `,
33	  message: css`
34	    position: relative;
35	    // prevent the textarea too long
36	    .${prefixCls}-input {
37	      max-height: 900px;
38	    }
39	  `,
40	}));
41	
42	export interface MessageItemProps {
43	  className?: string;
44	  defaultWorkflowExpanded?: boolean;
45	  disableEditing?: boolean;
46	  enableHistoryDivider?: boolean;
47	  endRender?: ReactNode;
48	  id: string;
49	  index: number;
50	  inPortalThread?: boolean;
51	  isLatestItem?: boolean;
52	}
53	
54	const MessageItem = memo<MessageItemProps>(
55	  ({
56	    className,
57	    defaultWorkflowExpanded,
58	    enableHistoryDivider,
59	    id,
60	    endRender,
61	    disableEditing,
62	    inPortalThread = false,
63	    index,
64	    isLatestItem,
65	  }) => {
66	    const topic = useConversationStore((s) => s.context.topicId);
67	
68	    // Get message from ConversationStore
69	    const message = useConversationStore(dataSelectors.getDisplayMessageById(id), isEqual);
70	    const role = message?.role;
71	
72	    const [editing, isMessageCreating] = useConversationStore((s) => [
