85	      async (event: MouseEvent<HTMLDivElement>) => {
86	        if (!role || (role !== 'user' && role !== 'assistant' && role !== 'assistantGroup')) return;
87	
88	        if (!message) return;
89	
90	        if (isDesktop) {
91	          const { electronSystemService } = await import('@/services/electron/system');
92	
93	          // Get selected text for context menu features like Look Up and Search
94	          const selection = window.getSelection();
95	          const selectionText = selection?.toString() || '';
96	
97	          electronSystemService.showContextMenu('chat', {
98	            content: message.content,
99	            hasError: !!message.error,
100	            messageId: id,
101	            // For assistantGroup, we treat it as assistant for context menu purposes
102	            role: message.role === 'assistantGroup' ? 'assistant' : message.role,
103	            selectionText,
104	          });
105	
106	          return;
107	        }
108	
109	        handleContextMenu(event);
110	      },
111	      [handleContextMenu, id, role, message],
112	    );
113	
114	    const renderContent = useCallback(() => {
115	      switch (role) {
116	        case 'user': {
117	          return <UserMessage disableEditing={disableEditing} id={id} index={index} />;
118	        }
119	
120	        case 'assistant': {
121	          return (
122	            <AssistantMessage
123	              disableEditing={disableEditing}
124	              id={id}
125	              index={index}
126	              isLatestItem={isLatestItem}
127	            />
128	          );
129	        }
130	
131	        case 'assistantGroup': {
132	          return (
133	            <AssistantGroupMessage
134	              defaultWorkflowExpanded={defaultWorkflowExpanded}
135	              disableEditing={disableEditing}
136	              id={id}
137	              index={index}
138	              isLatestItem={isLatestItem}
139	            />
140	          );
141	        }
142	
143	        case 'supervisor': {
144	          return (
145	            <SupervisorMessage
146	              disableEditing={disableEditing}
147	              id={id}
148	              index={index}
149	              isLatestItem={isLatestItem}
150	            />

