1	'use client';
2	
3	import type { AssistantContentBlock, EmojiReaction } from '@lobechat/types';
4	import isEqual from 'fast-deep-equal';
5	import type { MouseEventHandler } from 'react';
6	import { memo, Suspense, useCallback, useMemo } from 'react';
7	
8	import { MESSAGE_ACTION_BAR_PORTAL_ATTRIBUTES } from '@/const/messageActionPortal';
9	import { ChatItem } from '@/features/Conversation/ChatItem';
10	import { useOpenChatSettings } from '@/hooks/useInterceptingRoutes';
11	import dynamic from '@/libs/next/dynamic';
12	import { useAgentStore } from '@/store/agent';
13	import { builtinAgentSelectors } from '@/store/agent/selectors';
14	import { useGlobalStore } from '@/store/global';
15	import { useUserStore } from '@/store/user';
16	import { userGeneralSettingsSelectors, userProfileSelectors } from '@/store/user/selectors';
17	
18	import { ReactionDisplay } from '../../components/Reaction';
19	import { useAgentMeta } from '../../hooks';
20	import { dataSelectors, messageStateSelectors, useConversationStore } from '../../store';
21	import InterruptedHint from '../Assistant/components/InterruptedHint';
22	import Usage from '../components/Extras/Usage';
23	import MessageBranch from '../components/MessageBranch';
24	import {
25	  useSetMessageItemActionElementPortialContext,
26	  useSetMessageItemActionTypeContext,
27	} from '../Contexts/message-action-context';
28	import FileListViewer from '../User/components/FileListViewer';
29	import Group from './components/Group';
30	
31	const EditState = dynamic(() => import('./components/EditState'), {
32	  ssr: false,
33	});
34	
35	const actionBarHolder = (
36	  <div
37	    {...{ [MESSAGE_ACTION_BAR_PORTAL_ATTRIBUTES.assistantGroup]: '' }}
38	    style={{ height: '28px' }}
39	  />
40	);
41	interface GroupMessageProps {
42	  defaultWorkflowExpanded?: boolean;
43	  disableEditing?: boolean;
44	  id: string;
45	  index: number;
46	  isLatestItem?: boolean;
47	}
48	
49	const GroupMessage = memo<GroupMessageProps>(
50	  ({ defaultWorkflowExpanded, id, index, disableEditing }) => {
51	    // Get message and actionsConfig from ConversationStore
52	    const item = useConversationStore(dataSelectors.getDisplayMessageById(id), isEqual)!;
53	
54	    const { agentId, usage, createdAt, children, performance, model, provider, branch, metadata } =
55	      item;
56	    const avatar = useAgentMeta(agentId);
57	
58	    // Collect fileList from all children blocks
59	    const aggregatedFileList = useMemo(() => {
60	      if (!children || children.length === 0) return [];
61	      return children.flatMap((child: AssistantContentBlock) => child.fileList || []);
62	    }, [children]);
63	
64	    const isInbox = useAgentStore(builtinAgentSelectors.isInboxAgent);
65	    const [toggleSystemRole] = useGlobalStore((s) => [s.toggleSystemRole]);
66	    const openChatSettings = useOpenChatSettings();
67	
68	    // Get the latest message block from the group that doesn't contain tools
69	    const lastAssistantMsg = useConversationStore(
70	      dataSelectors.getGroupLatestMessageWithoutTools(id),
71	    );
72	
73	    const contentId = lastAssistantMsg?.id;
74	
75	    // Get editing and interrupted state from ConversationStore
76	    const editing = useConversationStore(messageStateSelectors.isMessageEditing(contentId || ''));
77	    // Check interrupted on both the group root and the active block, because
78	    // continuation runs attach their operations to lastBlockId (contentId),
79	    // not the group root.
80	    const groupInterrupted = useConversationStore(messageStateSelectors.isMessageInterrupted(id));
81	    const blockInterrupted = useConversationStore(
82	      messageStateSelectors.isMessageInterrupted(contentId || ''),
83	    );
84	    const interrupted = groupInterrupted || blockInterrupted;
85	
86	    const isDevMode = useUserStore((s) => userGeneralSettingsSelectors.config(s).isDevMode);
87	    const addReaction = useConversationStore((s) => s.addReaction);
88	    const removeReaction = useConversationStore((s) => s.removeReaction);
89	    const userId = useUserStore(userProfileSelectors.userId)!;
90	    const reactions: EmojiReaction[] = metadata?.reactions || [];
91	
92	    const handleReactionClick = useCallback(
93	      (emoji: string) => {
94	        const existing = reactions.find((r) => r.emoji === emoji);
95	        if (existing && existing.users.includes(userId)) {
96	          removeReaction(id, emoji);
97	        } else {
98	          addReaction(id, emoji);
99	        }
100	      },
101	      [id, reactions, addReaction, removeReaction],
102	    );
103	
104	    const isReactionActive = useCallback(
105	      (emoji: string) => {
106	        const reaction = reactions.find((r) => r.emoji === emoji);
107	        return !!reaction && reaction.users.includes(userId);
108	      },
109	      [reactions],
110	    );
111	
112	    const setMessageItemActionElementPortialContext =
113	      useSetMessageItemActionElementPortialContext();
114	    const setMessageItemActionTypeContext = useSetMessageItemActionTypeContext();
115	
116	    const onMouseEnter: MouseEventHandler<HTMLDivElement> = useCallback(
117	      (e) => {
118	        if (disableEditing) return;
119	        setMessageItemActionElementPortialContext(e.currentTarget);
120	        setMessageItemActionTypeContext({ id, index, type: 'assistantGroup' });
121	      },
122	      [
123	        disableEditing,
124	        id,
125	        index,
126	        setMessageItemActionElementPortialContext,
127	        setMessageItemActionTypeContext,
128	      ],
129	    );
130	
131	    const onAvatarClick = useCallback(() => {
132	      if (!isInbox) {
133	        toggleSystemRole(true);
134	      } else {
135	        openChatSettings();
136	      }
137	    }, [isInbox]);
138	
139	    return (
140	      <ChatItem
141	        showTitle
142	        avatar={avatar}
143	        placement={'left'}
144	        time={createdAt}
145	        actions={
146	          !disableEditing && (
147	            <>
148	              {isDevMode && branch && (
149	                <MessageBranch
150	                  activeBranchIndex={branch.activeBranchIndex}
151	                  count={branch.count}
152	                  messageId={id}
153	                />
154	              )}
155	              {actionBarHolder}
156	            </>
157	          )
158	        }
159	        onAvatarClick={onAvatarClick}
160	        onMouseEnter={onMouseEnter}
161	      >
162	        {children && children.length > 0 && (
163	          <Group
164	            blocks={children}
165	            content={lastAssistantMsg?.content}
166	            contentId={contentId}
167	            defaultWorkflowExpanded={defaultWorkflowExpanded}
168	            disableEditing={disableEditing}
169	            id={id}
170	            messageIndex={index}
171	          />
172	        )}
173	        {aggregatedFileList.length > 0 && (
174	          <div style={{ marginTop: 8 }}>
175	            <FileListViewer items={aggregatedFileList} />
176	          </div>
177	        )}
178	        {interrupted && <InterruptedHint />}
179	        {isDevMode && model && (
180	          <Usage model={model} performance={performance} provider={provider!} usage={usage} />
181	        )}
182	        {reactions.length > 0 && (
183	          <ReactionDisplay
184	            isActive={isReactionActive}
185	            messageId={id}
186	            reactions={reactions}
187	            onReactionClick={handleReactionClick}
188	          />
189	        )}
190	        <Suspense fallback={null}>
191	          {editing && contentId && <EditState content={lastAssistantMsg?.content} id={contentId} />}
192	        </Suspense>
193	      </ChatItem>
194	    );
195	  },
196	  isEqual,
197	);
198	
199	export default GroupMessage;
