6	import { LOADING_FLAT } from '@/const/message';
7	import { type AssistantContentBlock } from '@/types/index';
8	
9	import { messageStateSelectors, useConversationStore } from '../../../store';
10	import { MessageAggregationContext } from '../../Contexts/MessageAggregationContext';
11	import { areWorkflowToolsComplete, getPostToolAnswerSplitIndex } from '../toolDisplayNames';
12	import { CollapsedMessage } from './CollapsedMessage';
13	import GroupItem from './GroupItem';
14	import WorkflowCollapse from './WorkflowCollapse';
15	
16	const styles = createStaticStyles(({ css }) => {
17	  return {
18	    container: css`
19	      &:has(.tool-blocks) {
20	        width: 100%;
21	      }
22	    `,
23	  };
24	});
25	
26	interface GroupChildrenProps {
27	  blocks: AssistantContentBlock[];
28	  content?: string;
29	  contentId?: string;
30	  defaultWorkflowExpanded?: boolean;
31	  disableEditing?: boolean;
32	  id: string;
33	  messageIndex: number;
34	}
35	
36	interface PartitionedBlocks {
37	  answerBlocks: AssistantContentBlock[];
38	  /** True while generating if long post-tool answer was moved outside the fold (tool phase UI may show “done”). */
39	  postToolTailPromoted: boolean;
40	  workingBlocks: AssistantContentBlock[];
41	}
42	
43	const isEmptyBlock = (block: AssistantContentBlock) =>
44	  (!block.content || block.content === LOADING_FLAT) &&
45	  (!block.tools || block.tools.length === 0) &&
46	  !block.error &&
47	  !block.reasoning;
48	
49	/**
50	 * Check if a block contains any tool calls.
51	 */
52	const hasTools = (block: AssistantContentBlock): boolean => {
53	  return !!block.tools && block.tools.length > 0;
54	};
55	
56	const hasSubstantiveContent = (block: AssistantContentBlock): boolean => {
57	  const content = block.content?.trim();
58	  return !!content && content !== LOADING_FLAT;
59	};
60	
61	const hasReasoningContent = (block: AssistantContentBlock): boolean => {
62	  return !!block.reasoning?.content?.trim();
63	};
64	
65	const isTrailingReasoningCandidate = (block: AssistantContentBlock): boolean => {
66	  return hasReasoningContent(block) && !hasTools(block) && !block.error;
67	};
68	
69	const splitPostToolBlocks = (
70	  postBlocks: AssistantContentBlock[],
71	): Pick<PartitionedBlocks, 'answerBlocks' | 'workingBlocks'> => {
72	  const answerBlocks: AssistantContentBlock[] = [];
73	  const workingBlocks: AssistantContentBlock[] = [];
74	
75	  let index = 0;
76	  while (index < postBlocks.length) {
77	    const block = postBlocks[index]!;
78	    if (!isTrailingReasoningCandidate(block)) break;
79	
80	    workingBlocks.push({ ...block, content: '' });
81	
82	    if (hasSubstantiveContent(block) || (block.imageList?.length ?? 0) > 0) {
83	      answerBlocks.push({ ...block, reasoning: undefined });
84	    }
85	
86	    index += 1;
87	  }
88	
89	  answerBlocks.push(...postBlocks.slice(index));
90	
91	  return { answerBlocks, workingBlocks };
92	};
93	
94	/**
95	 * Partition blocks into "working phase" and "answer phase".
96	 *
97	 * Working phase: from first block with tools through last block with tools
98	 * (inclusive — interleaved content/reasoning blocks between tool blocks are included).
99	 *
100	 * Answer phase: blocks before the first tool block, plus blocks after the last tool
101	 * (or after detected post-tool “final answer” while still generating).
102	 */
103	const partitionBlocks = (
104	  blocks: AssistantContentBlock[],
105	  isGenerating: boolean,
106	): PartitionedBlocks => {
107	  let lastToolIndex = -1;
108	  for (let i = blocks.length - 1; i >= 0; i--) {
109	    if (hasTools(blocks[i])) {
110	      lastToolIndex = i;
111	      break;
112	    }
113	  }
114	
115	  if (lastToolIndex === -1) {
116	    return { answerBlocks: blocks, postToolTailPromoted: false, workingBlocks: [] };
117	  }
118	
119	  let firstToolIndex = 0;
120	  for (let i = 0; i < blocks.length; i++) {
121	    if (hasTools(blocks[i])) {
122	      firstToolIndex = i;
123	      break;
124	    }
125	  }
126	
127	  const preBlocks = blocks.slice(0, firstToolIndex);
128	
129	  if (isGenerating) {
130	    const toolsFlat = blocks.flatMap((b) => b.tools ?? []);
131	    const toolsPhaseComplete = areWorkflowToolsComplete(toolsFlat);
132	    let workingEndExclusive = blocks.length;
133	    let postToolTailPromoted = false;
134	    if (toolsPhaseComplete) {
135	      const split = getPostToolAnswerSplitIndex(blocks, lastToolIndex, toolsPhaseComplete, true);
136	      if (split != null) {
137	        workingEndExclusive = split;
138	        postToolTailPromoted = true;
139	      }
140	    }
141	
142	    return {
143	      answerBlocks: [...preBlocks, ...blocks.slice(workingEndExclusive)],
144	      postToolTailPromoted,
145	      workingBlocks: blocks.slice(firstToolIndex, workingEndExclusive),
146	    };
147	  }
148	
149	  const postBlocks = blocks.slice(lastToolIndex + 1);
150	  const postToolReasoning = splitPostToolBlocks(postBlocks);

