1	import { type ChatToolPayload } from '@lobechat/types';
2	import debug from 'debug';
3	import { type Redis } from 'ioredis';
4	
5	import { getAgentRuntimeRedisClient } from './redis';
6	
7	const log = debug('lobe-server:agent-runtime:stream-event-manager');
8	const timing = debug('lobe-server:agent-runtime:timing');
9	
10	const extractReasonFromError = (error: any): string | undefined => {
11	  if (!error) return undefined;
12	
13	  // ChatMessageError format: { body: { error: { message } }, message, type }
14	  if (error.body?.error?.message) return error.body.error.message;
15	  if (error.body?.message) return error.body.message;
16	
17	  // ChatCompletionErrorPayload format: { error: { message }, errorType }
18	  if (error.error?.error?.message) return error.error.error.message;
19	  if (error.error?.message) return error.error.message;
20	
21	  // Direct message (skip "[object Object]")
22	  if (error.message && error.message !== '[object Object]' && error.message !== 'error') {
23	    return error.message;
24	  }
25	
26	  return error.type || error.errorType || undefined;
27	};
28	
29	export const getDefaultReasonDetail = (finalState: any, reason?: string): string => {
30	  if (reason === 'error') {
31	    return extractReasonFromError(finalState?.error) || 'Agent runtime failed';
32	  }
33	
34	  if (reason === 'interrupted') {
35	    return extractReasonFromError(finalState?.error) || 'Agent runtime interrupted';
36	  }
37	
38	  return 'Agent runtime completed successfully';
39	};
40	
41	export interface StreamEvent {
42	  data: any;
43	  id?: string; // Redis Stream event ID
44	  operationId: string;
45	  stepIndex: number;
46	  timestamp: number;
47	  type:
48	    | 'agent_runtime_init'
49	    | 'agent_runtime_end'
50	    | 'stream_start'
51	    | 'stream_chunk'
52	    | 'stream_end'
53	    | 'stream_retry'
54	    | 'tool_start'
55	    | 'tool_end'
56	    | 'step_start'
57	    | 'step_complete'
58	    | 'error';
59	}
60	
61	export interface StreamChunkData {
62	  chunkType:
63	    | 'text'
64	    | 'reasoning'
65	    | 'tools_calling'
66	    | 'image'
67	    | 'grounding'
68	    | 'base64_image'
69	    | 'content_part'
70	    | 'reasoning_part';
71	  content?: string;
72	  /** Multimodal content parts (text + images) */
73	  contentParts?: Array<{ text: string; type: 'text' } | { image: string; type: 'image' }>;
74	  /** Grounding/search data */
75	  grounding?: any;
76	  /** Image list for base64_image chunks */
77	  imageList?: any[];
78	  images?: any[];
79	  reasoning?: string;
80	  /** Multimodal reasoning parts (text + images) */
81	  reasoningParts?: Array<{ text: string; type: 'text' } | { image: string; type: 'image' }>;
82	  toolsCalling?: ChatToolPayload[];
83	}
84	
85	export class StreamEventManager {
86	  private redis: Redis;
87	  private readonly STREAM_PREFIX = 'agent_runtime_stream';
88	  private readonly STREAM_RETENTION = 2 * 3600; // 2 hours
89	
90	  constructor() {
91	    const redisClient = getAgentRuntimeRedisClient();
92	    if (!redisClient) {
93	      throw new Error('Redis is not available. Please configure REDIS_URL environment variable.');
94	    }
95	    this.redis = redisClient;
96	  }
97	
98	  /**
99	   * Publish stream event to Redis Stream
100	   */
101	  async publishStreamEvent(
102	    operationId: string,
103	    event: Omit<StreamEvent, 'operationId' | 'timestamp'>,
104	  ): Promise<string> {
105	    const streamKey = `${this.STREAM_PREFIX}:${operationId}`;
106	
107	    const eventData: StreamEvent = {
108	      ...event,
109	      operationId,
110	      timestamp: Date.now(),
111	    };
112	
113	    try {
114	      const xaddStart = Date.now();
115	      const eventId = await this.redis.xadd(
116	        streamKey,
117	        'MAXLEN',
118	        '~',
119	        '1000', // Limit stream length to prevent memory overflow
120	        '*', // Auto-generate ID
121	        'type',
122	        eventData.type,
123	        'stepIndex',
124	        eventData.stepIndex.toString(),
125	        'operationId',
126	        eventData.operationId,
127	        'data',
128	        JSON.stringify(eventData.data),
129	        'timestamp',
130	        eventData.timestamp.toString(),
131	      );
132	      const xaddEnd = Date.now();
133	
134	      // Set expiration time
135	      await this.redis.expire(streamKey, this.STREAM_RETENTION);
136	
137	      log(
138	        'Published event %s for operation %s:%d',
139	        eventData.type,
140	        operationId,
141	        eventData.stepIndex,
142	      );
143	
144	      timing(
145	        '[%s:%d] Redis XADD %s at %d, took %dms',
146	        operationId,
147	        eventData.stepIndex,
148	        eventData.type,
149	        xaddStart,
150	        xaddEnd - xaddStart,
151	      );
152	
153	      return eventId as string;
154	    } catch (error) {
155	      console.error('[StreamEventManager] Failed to publish stream event:', error);
156	      throw error;
157	    }
158	  }
159	
160	  /**
161	   * Publish stream content chunk
162	   */
163	  async publishStreamChunk(
164	    operationId: string,
165	    stepIndex: number,
166	    chunkData: StreamChunkData,
167	  ): Promise<string> {
