9	
10	const extractReasonFromError = (error: any): string | undefined => {
11	  if (!error) return undefined;
12	
13	  // ChatMessageError format: { body: { error: { message } }, message, type }
14	  if (error.body?.error?.message) return error.body.error.message;
15	  if (error.body?.message) return error.body.message;
16	
17	  // ChatCompletionErrorPayload format: { error: { message }, errorType }
18	  if (error.error?.error?.message) return error.error.error.message;
19	  if (error.error?.message) return error.error.message;
20	
21	  // Direct message (skip "[object Object]")
22	  if (error.message && error.message !== '[object Object]' && error.message !== 'error') {
23	    return error.message;
24	  }
25	
26	  return error.type || error.errorType || undefined;
27	};
28	
29	export const getDefaultReasonDetail = (finalState: any, reason?: string): string => {
30	  if (reason === 'error') {
31	    return extractReasonFromError(finalState?.error) || 'Agent runtime failed';
32	  }
33	
34	  if (reason === 'interrupted') {
35	    return extractReasonFromError(finalState?.error) || 'Agent runtime interrupted';
36	  }
37	
38	  return 'Agent runtime completed successfully';
39	};
