85	export class StreamEventManager {
86	  private redis: Redis;
87	  private readonly STREAM_PREFIX = 'agent_runtime_stream';
88	  private readonly STREAM_RETENTION = 2 * 3600; // 2 hours
89	
90	  constructor() {
91	    const redisClient = getAgentRuntimeRedisClient();
92	    if (!redisClient) {
93	      throw new Error('Redis is not available. Please configure REDIS_URL environment variable.');
94	    }
95	    this.redis = redisClient;
96	  }
97	
98	  /**
99	   * Publish stream event to Redis Stream
100	   */
101	  async publishStreamEvent(
102	    operationId: string,
103	    event: Omit<StreamEvent, 'operationId' | 'timestamp'>,
104	  ): Promise<string> {
105	    const streamKey = `${this.STREAM_PREFIX}:${operationId}`;
106	
107	    const eventData: StreamEvent = {
108	      ...event,
109	      operationId,
110	      timestamp: Date.now(),
111	    };
112	
113	    try {
114	      const xaddStart = Date.now();
115	      const eventId = await this.redis.xadd(
116	        streamKey,
117	        'MAXLEN',
118	        '~',
119	        '1000', // Limit stream length to prevent memory overflow
120	        '*', // Auto-generate ID
121	        'type',
122	        eventData.type,
123	        'stepIndex',
124	        eventData.stepIndex.toString(),
125	        'operationId',
126	        eventData.operationId,
127	        'data',
128	        JSON.stringify(eventData.data),
129	        'timestamp',
130	        eventData.timestamp.toString(),
131	      );
132	      const xaddEnd = Date.now();
133	
134	      // Set expiration time
135	      await this.redis.expire(streamKey, this.STREAM_RETENTION);
136	
137	      log(
138	        'Published event %s for operation %s:%d',
139	        eventData.type,
140	        operationId,
141	        eventData.stepIndex,
142	      );
143	
144	      timing(
145	        '[%s:%d] Redis XADD %s at %d, took %dms',
146	        operationId,
147	        eventData.stepIndex,
148	        eventData.type,
149	        xaddStart,
150	        xaddEnd - xaddStart,
151	      );
152	
153	      return eventId as string;
154	    } catch (error) {
155	      console.error('[StreamEventManager] Failed to publish stream event:', error);
156	      throw error;
157	    }
158	  }
