93	export class ConversationLifecycleActionImpl {
94	  readonly #get: () => ChatStore;
95	
96	  constructor(set: Setter, get: () => ChatStore, _api?: unknown) {
97	    void _api;
98	    void set;
99	    this.#get = get;
100	  }
101	
102	  sendMessage = async ({
103	    message,
104	    editorData: inputEditorData,
105	    files,
106	    onlyAddUserMessage,
107	    context,
108	    messages: inputMessages,
109	    parentId: inputParentId,
110	    pageSelections,
111	  }: SendMessageWithContextParams): Promise<SendMessageResult | undefined> => {
112	    let editorData = inputEditorData;
113	    const { internal_execAgentRuntime, mainInputEditor } = this.#get();
114	    const selectedSkills = parseSelectedSkillsFromEditorData(editorData);
115	    const selectedTools = parseSelectedToolsFromEditorData(editorData);
116	    const mentionedAgents = parseMentionedAgentsFromEditorData(editorData);
117	
118	    // Use context from params (required)
119	    const { agentId } = context;
120	    // If creating new thread (isNew + scope='thread'), threadId will be created by server
