122	    // Build newThread params for server from new context format
123	    // Only create newThread if we have both sourceMessageId and threadType
124	    const newThread =
125	      isCreatingNewThread && context.sourceMessageId && context.threadType
126	        ? {
127	            sourceMessageId: context.sourceMessageId,
128	            type: context.threadType as ChatThreadType,
129	          }
130	        : undefined;
131	
132	    if (!agentId) return;
133	
134	    // ── Command Bus: extract and process built-in commands from editorData ──
135	    const commandOverrides: CommandSendOverrides = processCommands({
136	      message,
137	      editorData,
138	      files,
139	      onlyAddUserMessage,
140	      context,
141	      messages: inputMessages,
142	      parentId: inputParentId,
143	      pageSelections,
144	    });
145	
146	    // /compact — directly compress context without sending any message
147	    if (commandOverrides.triggerCompression) {
148	      const compressContext = { ...context };
149	      if (
150	        compressContext.topicId &&
151	        !hasRunningCompressionOperation(Object.values(this.#get().operations), compressContext)
152	      ) {
153	        await this.executeCompression(compressContext, '');
154	      }
155	      return;
156	    }
157	
158	    // /newTopic — force a fresh topic regardless of current context
159	    let forceNewTopicFromExisting = false;
160	    if (commandOverrides.forceNewTopic) {
161	      const hasFile = files && files.length > 0;
162	      // If no message content besides the action tag and no files, just navigate to a new topic without sending
163	      if (!hasNonActionContent(editorData) && !hasFile) {
164	        await this.#get().switchTopic(null);
165	        return;
166	      }
167	
168	      if (context.topicId) {
169	        const originalTopic = topicSelectors.getTopicById(context.topicId)(this.#get());
170	        const topicTitle = originalTopic?.title || '';
171	        // Inject referTopic into content for LLM context
172	        const referTag = `<refer_topic name="${topicTitle}" id="${context.topicId}" />`;
173	        message = `${referTag}\n${message}`;
174	        // Inject refer-topic node into editorData for rich text display
175	        editorData = injectReferTopicNode(editorData, context.topicId, topicTitle);
176	        forceNewTopicFromExisting = true;
177	      }
178	      context = { ...context, topicId: undefined };
179	    }
180	
181	    // When creating new thread, override threadId to undefined (server will create it)
182	    // Check if current agentId is the supervisor agent of the group
183	    let isGroupSupervisor = false;
184	    if (context.groupId) {
185	      const group = agentGroupByIdSelectors.groupById(context.groupId)(getChatGroupStoreState());
186	      isGroupSupervisor = group?.supervisorAgentId === agentId;
187	    }
188	    // In non-group context, @agent mentions make the current agent act as supervisor
189	    const hasMentionedAgents = !context.groupId && mentionedAgents.length > 0;
190	
191	    const operationContext = {
192	      ...context,
193	      ...(isCreatingNewThread && { threadId: undefined }),
194	      // Only set isSupervisor for actual group supervisors — NOT for @agent mentions.
195	      // isSupervisor triggers group-specific UI rendering (SupervisorMessage with group avatars).
196	      ...(isGroupSupervisor && { isSupervisor: true }),
197	    };
198	
199	    const fileIdList = files?.map((f) => f.id);
200	
201	    // Enrich selected skills/tools with preloaded content, injected directly
202	    // via SelectedSkillInjector/SelectedToolInjector — no fake tool-call preload messages
203	    const enrichedSelectedSkills = await resolveSelectedSkillsWithContent({
204	      message,
205	      selectedSkills,
206	    });
207	    const enrichedSelectedTools = resolveSelectedToolsWithContent({
208	      message,
209	      selectedTools,
210	    });
211	
212	    const hasFile = !!fileIdList && fileIdList.length > 0;
213	
214	    // if message is empty or no files, then stop
215	    if (!message && !hasFile) return;
216	
217	    // ━━━ Message Queue: enqueue if agent is currently running ━━━
218	    // Check if there's a running execAgentRuntime operation in the current context.
219	    // If so, enqueue the message instead of starting a new operation.
220	    const currentContextKey = messageMapKey(operationContext);
221	    const contextOpIds = this.#get().operationsByContext[currentContextKey] || [];
222	    const runningAgentOp = contextOpIds
223	      .map((id) => this.#get().operations[id])
224	      .find((op) => op && op.type === 'execAgentRuntime' && op.status === 'running');
225	
226	    if (runningAgentOp) {
227	      this.#get().enqueueMessage(
228	        currentContextKey,
229	        {
230	          id: nanoid(),
231	          content: message,
232	          editorData: editorData ?? undefined,
233	          files: fileIdList,
234	          interruptMode: 'soft',
235	          createdAt: Date.now(),
236	        },
237	        runningAgentOp.id,
238	      );
239	      return;
240	    }
241	
242	    if (onlyAddUserMessage) {
243	      await this.#get().addUserMessage({ message, fileList: fileIdList });
244	
245	      return;
246	    }
247	
248	    // Use provided messages or query from store
249	    // For /newTopic from existing topic, start with empty message list (fresh topic)
250	    const contextKey = messageMapKey(context);

