343	    // ── External agent mode: delegate to heterogeneous agent CLI (desktop only) ──
344	    // Per-agent heterogeneousProvider config takes priority over the global gateway mode.
345	    const agentConfig = agentSelectors.getAgentConfigById(agentId)(getAgentStoreState());
346	    const heterogeneousProvider = agentConfig?.agencyConfig?.heterogeneousProvider;
347	    if (isDesktop && heterogeneousProvider?.type === 'claudecode') {
348	      // Persist messages to DB first (same as client mode)
349	      let heteroData: SendMessageServerResponse | undefined;
350	      try {
351	        const { model, provider } =
352	          agentSelectors.getAgentConfigById(agentId)(getAgentStoreState());
353	        heteroData = await aiChatService.sendMessageInServer(
354	          {
355	            agentId: operationContext.agentId,
356	            groupId: operationContext.groupId ?? undefined,
357	            newAssistantMessage: { model, provider: provider! },
358	            newTopic: !operationContext.topicId
359	              ? {
360	                  title: message.slice(0, 20) || t('defaultTitle', { ns: 'topic' }),
361	                  topicMessageIds: messages.map((m) => m.id),
362	                }
363	              : undefined,
364	            newUserMessage: {
365	              content: message,
366	              editorData,
367	              files: fileIdList,
368	              pageSelections,
369	              parentId,
370	            },
371	            threadId: operationContext.threadId ?? undefined,
372	            topicId: operationContext.topicId ?? undefined,
373	          },
374	          abortController,
375	        );
376	      } catch (e) {
377	        console.error('[HeterogeneousAgent] Failed to persist messages:', e);
378	        this.#get().failOperation(operationId, {
379	          message: e instanceof Error ? e.message : 'Unknown error',
380	          type: 'HeterogeneousAgentError',
381	        });
382	        return;
383	      }
384	
385	      if (!heteroData) return;
386	
387	      // Update context with server-created topicId
388	      const heteroContext = {
389	        ...operationContext,
390	        topicId: heteroData.topicId ?? operationContext.topicId,
391	      };
392	
393	      // Replace optimistic messages with persisted ones
394	      this.#get().replaceMessages(heteroData.messages, {
395	        action: 'sendMessage/serverResponse',
396	        context: heteroContext,
397	      });
398	
399	      // Handle new topic creation
400	      if (heteroData.isCreateNewTopic && heteroData.topicId) {
401	        if (heteroData.topics) {
402	          const pageSize = systemStatusSelectors.topicPageSize(useGlobalStore.getState());
403	          this.#get().internal_updateTopics(operationContext.agentId, {
404	            groupId: operationContext.groupId,
405	            items: heteroData.topics.items,
406	            pageSize,
407	            total: heteroData.topics.total,
408	          });
409	        }
410	        await this.#get().switchTopic(heteroData.topicId, {
411	          clearNewKey: true,
412	          skipRefreshMessage: true,
413	        });
414	      }
415	
416	      // Clean up temp messages
417	      this.#get().internal_dispatchMessage(
418	        { ids: [tempId, tempAssistantId], type: 'deleteMessages' },
419	        { operationId },
420	      );
421	
422	      // Complete sendMessage operation, start ACP execution as child operation
423	      this.#get().completeOperation(operationId);
424	
425	      if (heteroData.topicId) this.#get().internal_updateTopicLoading(heteroData.topicId, true);
426	
427	      // Start heterogeneous agent execution
428	      const { operationId: heteroOpId } = this.#get().startOperation({
429	        context: heteroContext,
430	        label: 'Heterogeneous Agent Execution',
431	        parentOperationId: operationId,
432	        type: 'execHeterogeneousAgent',
433	      });
434	
435	      this.#get().associateMessageWithOperation(heteroData.assistantMessageId, heteroOpId);
436	
437	      try {
438	        const { executeHeterogeneousAgent } = await import('./heterogeneousAgentExecutor');
439	        const workingDirectory =
440	          agentByIdSelectors.getAgentWorkingDirectoryById(agentId)(getAgentStoreState());
441	        // Extract imageList from the persisted user message (chatUploadFileList
442	        // may already be cleared by this point, so we read from DB instead)
443	        const userMsg = heteroData.messages.find((m: any) => m.id === heteroData.userMessageId);
444	        const persistedImageList = userMsg?.imageList;
445	
446	        await executeHeterogeneousAgent(() => this.#get(), {
447	          assistantMessageId: heteroData.assistantMessageId,
448	          context: heteroContext,
449	          heterogeneousProvider,
450	          imageList: persistedImageList?.length ? persistedImageList : undefined,
451	          message,
452	          operationId: heteroOpId,
453	          workingDirectory,
454	        });
455	      } catch (e) {
456	        console.error('[HeterogeneousAgent] Execution failed:', e);
457	        this.#get().failOperation(heteroOpId, {
458	          message: e instanceof Error ? e.message : 'Unknown error',
459	          type: 'HeterogeneousAgentError',
460	        });
461	      }
462	
463	      if (heteroData.topicId) this.#get().internal_updateTopicLoading(heteroData.topicId, false);
464	
465	      return {
466	        assistantMessageId: heteroData.assistantMessageId,
467	        userMessageId: heteroData.userMessageId,
468	      };
469	    }

