1	import type { AssistantContentBlock, UIChatMessage } from '@lobechat/types';
2	
3	export interface ResolvedAssistantGroup {
4	  assistantId: string;
5	  blocks: AssistantContentBlock[];
6	  instruction?: string;
7	}
8	
9	/**
10	 * Resolve assistant group blocks from a thread/conversation message list.
11	 * Prefers `role === 'assistantGroup'` children; falls back to a plain `assistant` message as a single block.
12	 */
13	export function resolveAssistantGroupFromMessages(
14	  messages: UIChatMessage[] | undefined | null,
15	): ResolvedAssistantGroup {
16	  if (!messages || messages.length === 0) {
17	    return { assistantId: '', blocks: [] };
18	  }
19	
20	  const assistantGroupMessage = messages.find((item) => item.role === 'assistantGroup');
21	  const userMessage = messages.find((item) => item.role === 'user');
22	
23	  if (assistantGroupMessage) {
24	    return {
25	      assistantId: assistantGroupMessage.id ?? '',
26	      blocks: assistantGroupMessage.children ?? [],
27	      instruction: userMessage?.content,
28	    };
29	  }
30	
31	  const assistantMessage = messages.find((item) => item.role === 'assistant');
32	  if (assistantMessage) {
33	    const block: AssistantContentBlock = {
34	      content: assistantMessage.content || '',
35	      id: assistantMessage.id,
36	    };
37	
38	    if (assistantMessage.error) block.error = assistantMessage.error;
39	    if (assistantMessage.reasoning) block.reasoning = assistantMessage.reasoning;
40	
41	    return {
42	      assistantId: assistantMessage.id ?? '',
43	      blocks: [block],
44	      instruction: userMessage?.content,
45	    };
46	  }
47	
48	  return { assistantId: '', blocks: [] };
49	}
50

