1	/**
2	 * Heterogeneous Agent Adapter Types
3	 *
4	 * Adapters convert external agent protocol events into a unified
5	 * HeterogeneousAgentEvent format, which maps 1:1 to LobeHub's
6	 * AgentStreamEvent and can be fed directly into createGatewayEventHandler().
7	 *
8	 * Architecture:
9	 *   Claude Code stream-json ──→ ClaudeCodeAdapter ──→ HeterogeneousAgentEvent[]
10	 *   Codex CLI output         ──→ CodexAdapter      ──→ HeterogeneousAgentEvent[]  (future)
11	 *   ACP JSON-RPC             ──→ ACPAdapter        ──→ HeterogeneousAgentEvent[]  (future)
12	 */
13	
14	// ─── Unified Event Format ───
15	// Mirrors AgentStreamEvent from src/libs/agent-stream/types.ts
16	// but defined here so the package is self-contained.
17	
18	export type HeterogeneousEventType =
19	  | 'stream_start'
20	  | 'stream_chunk'
21	  | 'stream_end'
22	  | 'tool_start'
23	  | 'tool_end'
24	  /**
25	   * Tool result content arrived. ACP-specific (Gateway tools run on server,
26	   * so server handles result persistence). Executor should update the tool
27	   * message in DB with this content.
28	   */
29	  | 'tool_result'
30	  | 'step_complete'
31	  | 'agent_runtime_end'
32	  | 'error';
33	
34	export type StreamChunkType = 'text' | 'reasoning' | 'tools_calling';
35	
36	export interface HeterogeneousAgentEvent {
37	  data: any;
38	  stepIndex: number;
39	  timestamp: number;
40	  type: HeterogeneousEventType;
41	}
42	
43	/** Data shape for stream_start events */
44	export interface StreamStartData {
45	  assistantMessage?: { id: string };
46	  model?: string;
47	  provider?: string;
48	}
49	
50	/** Data shape for stream_chunk events */
51	export interface StreamChunkData {
52	  chunkType: StreamChunkType;
53	  content?: string;
54	  reasoning?: string;
55	  toolsCalling?: ToolCallPayload[];
56	}
57	
58	/** Data shape for tool_end events */
59	export interface ToolEndData {
60	  isSuccess: boolean;
61	  toolCallId: string;
62	}
63	
64	/** Data shape for tool_result events (ACP-specific) */
65	export interface ToolResultData {
66	  content: string;
67	  isError?: boolean;
68	  toolCallId: string;
69	}
70	
71	/** Tool call payload (matches ChatToolPayload shape) */
72	export interface ToolCallPayload {
73	  apiName: string;
74	  arguments: string;
75	  id: string;
76	  identifier: string;
77	  type: string;
78	}
79	
80	// ─── Adapter Interface ───
81	
82	/**
83	 * Stateful adapter that converts raw agent events to HeterogeneousAgentEvent[].
84	 *
85	 * Adapters maintain internal state (e.g., pending tool calls) to correctly
86	 * emit lifecycle events like tool_start / tool_end.
87	 */
88	export interface AgentEventAdapter {
89	  /**
90	   * Convert a single raw event into zero or more HeterogeneousAgentEvents.
91	   */
92	  adapt: (raw: any) => HeterogeneousAgentEvent[];
93	
94	  /**
95	   * Flush any buffered events (call at end of stream).
96	   */
97	  flush: () => HeterogeneousAgentEvent[];
98	
99	  /** The session ID extracted from the agent's init event (for multi-turn resume). */
100	  sessionId?: string;
101	}
102	
103	// ─── Agent Process Config ───
104	
105	/**
106	 * Configuration for spawning an external agent CLI process.
107	 * Agent-agnostic — works for claude, codex, kimi-cli, etc.
108	 */
109	export interface AgentProcessConfig {
110	  /** Adapter type key (e.g., 'claude-code', 'codex', 'kimi-cli') */
111	  adapterType: string;
112	  /** CLI arguments appended after built-in flags */
113	  args?: string[];
114	  /** Command to execute (e.g., 'claude', 'codex') */
115	  command: string;
116	  /** Working directory */
117	  cwd?: string;
118	  /** Environment variables */
119	  env?: Record<string, string>;
120	}
121	
122	/**
123	 * Registry of built-in CLI flag presets per agent type.
124	 * The Electron controller uses this to construct the full spawn args.
125	 */
126	export interface AgentCLIPreset {
127	  /** Base CLI arguments (e.g., ['-p', '--output-format', 'stream-json', '--verbose']) */
128	  baseArgs: string[];
129	  /** How to pass the prompt (e.g., 'positional' = last arg, 'stdin' = pipe to stdin) */
130	  promptMode: 'positional' | 'stdin';
131	  /** How to resume a session (e.g., ['--resume', '{sessionId}']) */
132	  resumeArgs?: (sessionId: string) => string[];
133	}
134

