1	/**
2	 * Claude Code Adapter
3	 *
4	 * Converts Claude Code CLI `--output-format stream-json --verbose` (ndjson)
5	 * events into unified HeterogeneousAgentEvent[] that the executor feeds into
6	 * LobeHub's Gateway event handler.
7	 *
8	 * Stream-json event shapes (from real CLI output):
9	 *
10	 *   {type: 'system', subtype: 'init', session_id, model, ...}
11	 *   {type: 'assistant', message: {id, content: [{type: 'thinking', thinking}], ...}}
12	 *   {type: 'assistant', message: {id, content: [{type: 'tool_use', id, name, input}], ...}}
13	 *   {type: 'user', message: {content: [{type: 'tool_result', tool_use_id, content}]}}
14	 *   {type: 'assistant', message: {id: <NEW>, content: [{type: 'text', text}], ...}}
15	 *   {type: 'result', is_error, result, ...}
16	 *   {type: 'rate_limit_event', ...}  (ignored)
17	 *
18	 * Key characteristics:
19	 * - Each content block (thinking / tool_use / text) streams in its OWN assistant event
20	 * - Multiple events can share the same `message.id` — these are ONE LLM turn
21	 * - When `message.id` changes, a new LLM turn has begun — new DB assistant message
22	 * - `tool_result` blocks are in `type: 'user'` events, not assistant events
23	 */
24	
25	import type {
26	  AgentCLIPreset,
27	  AgentEventAdapter,
28	  HeterogeneousAgentEvent,
29	  StreamChunkData,
30	  ToolCallPayload,
31	  ToolResultData,
32	} from '../types';
33	
34	// ─── CLI Preset ───
35	
36	export const claudeCodePreset: AgentCLIPreset = {
37	  baseArgs: [
38	    '-p',
39	    '--output-format',
40	    'stream-json',
41	    '--verbose',
42	    '--permission-mode',
43	    'acceptEdits',
44	  ],
45	  promptMode: 'positional',
46	  resumeArgs: (sessionId) => ['--resume', sessionId],
47	};
48	
49	// ─── Adapter ───
50	
51	export class ClaudeCodeAdapter implements AgentEventAdapter {
52	  sessionId?: string;
53	
54	  /** Pending tool_use ids awaiting their tool_result */
55	  private pendingToolCalls = new Set<string>();
56	  private started = false;
57	  private stepIndex = 0;
58	  /** Track current message.id to detect step boundaries */
59	  private currentMessageId: string | undefined;
60	
61	  adapt(raw: any): HeterogeneousAgentEvent[] {
62	    if (!raw || typeof raw !== 'object') return [];
63	
64	    switch (raw.type) {
65	      case 'system': {
66	        return this.handleSystem(raw);
67	      }
68	      case 'assistant': {
69	        return this.handleAssistant(raw);
70	      }
71	      case 'user': {
72	        return this.handleUser(raw);
73	      }
74	      case 'result': {
75	        return this.handleResult(raw);
76	      }
77	      default: {
78	        return [];
79	      } // rate_limit_event, etc.
80	    }
81	  }
82	
83	  flush(): HeterogeneousAgentEvent[] {
84	    // Close any still-open tools (shouldn't happen in normal flow, but be safe)
85	    const events = [...this.pendingToolCalls].map((id) =>
86	      this.makeEvent('tool_end', { isSuccess: true, toolCallId: id }),
87	    );
88	    this.pendingToolCalls.clear();
89	    return events;
90	  }
91	
92	  // ─── Private handlers ───
93	
94	  private handleSystem(raw: any): HeterogeneousAgentEvent[] {
95	    if (raw.subtype !== 'init') return [];
96	    this.sessionId = raw.session_id;
97	    this.started = true;
98	    return [
99	      this.makeEvent('stream_start', {
100	        model: raw.model,
101	        provider: 'claude-code',
102	      }),
103	    ];
104	  }
105	
106	  private handleAssistant(raw: any): HeterogeneousAgentEvent[] {
107	    const content = raw.message?.content;
108	    if (!Array.isArray(content)) return [];
109	
110	    const events: HeterogeneousAgentEvent[] = [];
111	    const messageId = raw.message?.id;
112	
113	    if (!this.started) {
114	      this.started = true;
115	      this.currentMessageId = messageId;
116	      events.push(
117	        this.makeEvent('stream_start', {
118	          model: raw.message?.model,
119	          provider: 'claude-code',
120	        }),
121	      );
122	    } else if (messageId && messageId !== this.currentMessageId) {
123	      if (this.currentMessageId === undefined) {
124	        // First assistant message after init — just record the ID, no step boundary.
125	        // The init stream_start already primed the executor with the pre-created
126	        // assistant message, so we don't need a new one.
127	        this.currentMessageId = messageId;
128	      } else {
129	        // New message.id = new LLM turn. Emit stream_end for previous step,
130	        // then stream_start for the new one so executor creates a new assistant message.
131	        this.currentMessageId = messageId;
132	        this.stepIndex++;
133	        events.push(this.makeEvent('stream_end', {}));
134	        events.push(
135	          this.makeEvent('stream_start', {
136	            model: raw.message?.model,
137	            newStep: true,
138	            provider: 'claude-code',
139	          }),
140	        );
141	      }
142	    }
143	
144	    // Per-turn model + usage snapshot — emitted as 'step_complete'-like
145	    // metadata event so executor can track latest model and accumulated usage.
146	    if (raw.message?.model || raw.message?.usage) {
147	      events.push(
148	        this.makeEvent('step_complete', {
149	          model: raw.message?.model,
150	          phase: 'turn_metadata',
151	          usage: raw.message?.usage,
152	        }),
153	      );
154	    }
155	
156	    // Each content array here is usually ONE block (thinking OR tool_use OR text)
157	    // but we handle multiple defensively.
158	    const textParts: string[] = [];
159	    const reasoningParts: string[] = [];
160	    const newToolCalls: ToolCallPayload[] = [];
161	
162	    for (const block of content) {
163	      switch (block.type) {
164	        case 'text': {
165	          if (block.text) textParts.push(block.text);
166	          break;
167	        }
168	        case 'thinking': {
169	          if (block.thinking) reasoningParts.push(block.thinking);
170	          break;
171	        }
172	        case 'tool_use': {
173	          const toolPayload: ToolCallPayload = {
174	            apiName: block.name,
175	            arguments: JSON.stringify(block.input || {}),
176	            id: block.id,
177	            identifier: 'claude-code',
178	            type: 'default',
179	          };
180	          newToolCalls.push(toolPayload);
181	          this.pendingToolCalls.add(block.id);
182	          break;
183	        }
184	      }
185	    }
186	
187	    if (textParts.length > 0) {
188	      events.push(this.makeChunkEvent({ chunkType: 'text', content: textParts.join('') }));
189	    }
190	    if (reasoningParts.length > 0) {
191	      events.push(
192	        this.makeChunkEvent({ chunkType: 'reasoning', reasoning: reasoningParts.join('') }),
193	      );
194	    }
195	    if (newToolCalls.length > 0) {
196	      events.push(this.makeChunkEvent({ chunkType: 'tools_calling', toolsCalling: newToolCalls }));
197	      // Also emit tool_start for each — the handler's tool_start is a no-op
198	      // but it's semantically correct for the lifecycle.
199	      for (const t of newToolCalls) {
200	        events.push(this.makeEvent('tool_start', { toolCalling: t }));
201	      }
202	    }
203	
204	    return events;
205	  }
206	
207	  /**
208	   * Handle user events — these contain tool_result blocks.
209	   * NOTE: In Claude Code, tool results are emitted as `type: 'user'` events
210	   * (representing the synthetic user turn that feeds results back to the LLM).
211	   */
212	  private handleUser(raw: any): HeterogeneousAgentEvent[] {
213	    const content = raw.message?.content;
214	    if (!Array.isArray(content)) return [];
215	
216	    const events: HeterogeneousAgentEvent[] = [];
217	
218	    for (const block of content) {
219	      if (block.type !== 'tool_result') continue;
220	      const toolCallId: string | undefined = block.tool_use_id;
221	      if (!toolCallId) continue;
222	
223	      const resultContent =
224	        typeof block.content === 'string'
225	          ? block.content
226	          : Array.isArray(block.content)
227	            ? block.content
228	                .map((c: any) => c.text || c.content || '')
229	                .filter(Boolean)
230	                .join('\n')
231	            : JSON.stringify(block.content || '');
232	
233	      // Emit tool_result for executor to persist content to tool message
234	      events.push(
235	        this.makeEvent('tool_result', {
236	          content: resultContent,
237	          isError: !!block.is_error,
238	          toolCallId,
239	        } satisfies ToolResultData),
240	      );
241	
242	      // Then emit tool_end (signals handler to refresh tool result UI)
243	      if (this.pendingToolCalls.has(toolCallId)) {
244	        this.pendingToolCalls.delete(toolCallId);
245	        events.push(this.makeEvent('tool_end', { isSuccess: !block.is_error, toolCallId }));
246	      }
247	    }
248	
249	    return events;
250	  }
251	
252	  private handleResult(raw: any): HeterogeneousAgentEvent[] {
253	    const finalEvent: HeterogeneousAgentEvent = raw.is_error
254	      ? this.makeEvent('error', {
255	          error: raw.result || 'Agent execution failed',
256	          message: raw.result || 'Agent execution failed',
257	        })
258	      : this.makeEvent('agent_runtime_end', {});
259	
260	    return [this.makeEvent('stream_end', {}), finalEvent];
261	  }
262	
263	  // ─── Event factories ───
264	
265	  private makeEvent(type: HeterogeneousAgentEvent['type'], data: any): HeterogeneousAgentEvent {
266	    return { data, stepIndex: this.stepIndex, timestamp: Date.now(), type };
267	  }
268	
269	  private makeChunkEvent(data: StreamChunkData): HeterogeneousAgentEvent {
270	    return { data, stepIndex: this.stepIndex, timestamp: Date.now(), type: 'stream_chunk' };
271	  }
272	}
273

