1	/**
2	 * End-to-end integration test for ClaudeCodeAdapter.
3	 *
4	 * Simulates a realistic Claude Code CLI stream-json session with multiple steps:
5	 *   init → thinking → text → tool_use → tool_result → new step → text → result
6	 *
7	 * Verifies the complete event pipeline that the executor would consume.
8	 */
9	import { describe, expect, it } from 'vitest';
10	
11	import { ClaudeCodeAdapter } from './claudeCode';
12	
13	/**
14	 * Simulate a realistic multi-step Claude Code session.
15	 *
16	 * Scenario: CC reads a file, then writes a fix in a second LLM turn.
17	 */
18	const simulatedStream = [
19	  // 1. System init
20	  {
21	    model: 'claude-sonnet-4-6',
22	    session_id: 'sess_abc123',
23	    subtype: 'init',
24	    tools: ['Read', 'Write', 'Bash'],
25	    type: 'system',
26	  },
27	  // 2. First assistant turn — thinking + tool_use (Read)
28	  {
29	    message: {
30	      content: [
31	        { thinking: 'Let me read the file first to understand the issue.', type: 'thinking' },
32	      ],
33	      id: 'msg_01',
34	      model: 'claude-sonnet-4-6',
35	      role: 'assistant',
36	      usage: { input_tokens: 500, output_tokens: 100 },
37	    },
38	    type: 'assistant',
39	  },
40	  {
41	    message: {
42	      content: [
43	        { id: 'toolu_read_1', input: { file_path: '/src/app.ts' }, name: 'Read', type: 'tool_use' },
44	      ],
45	      id: 'msg_01',
46	      model: 'claude-sonnet-4-6',
47	      role: 'assistant',
48	      usage: { input_tokens: 500, output_tokens: 150 },
49	    },
50	    type: 'assistant',
51	  },
52	  // 3. Tool result (user event)
53	  {
54	    message: {
55	      content: [
56	        {
57	          content: 'export function add(a: number, b: number) {\n  return a - b; // BUG\n}',
58	          tool_use_id: 'toolu_read_1',
59	          type: 'tool_result',
60	        },
61	      ],
62	      role: 'user',
63	    },
64	    type: 'user',
65	  },
66	  // 4. Second assistant turn — NEW message.id = new step
67	  {
68	    message: {
69	      content: [
70	        { thinking: 'Found the bug: subtract instead of add. Let me fix it.', type: 'thinking' },
71	      ],
72	      id: 'msg_02',
73	      model: 'claude-sonnet-4-6',
74	      role: 'assistant',
75	      usage: { input_tokens: 800, output_tokens: 80 },
76	    },
77	    type: 'assistant',
78	  },
79	  {
80	    message: {
81	      content: [
82	        {
83	          id: 'toolu_write_1',
84	          input: {
85	            content: 'export function add(a: number, b: number) {\n  return a + b;\n}',
86	            file_path: '/src/app.ts',
87	          },
88	          name: 'Write',
89	          type: 'tool_use',
90	        },
91	      ],
92	      id: 'msg_02',
93	      model: 'claude-sonnet-4-6',
94	      role: 'assistant',
95	      usage: { input_tokens: 800, output_tokens: 200 },
96	    },
97	    type: 'assistant',
98	  },
99	  // 5. Write tool result
100	  {
101	    message: {
102	      content: [
103	        {
104	          content: 'File written successfully.',
105	          tool_use_id: 'toolu_write_1',
106	          type: 'tool_result',
107	        },
108	      ],
109	      role: 'user',
110	    },
111	    type: 'user',
112	  },
113	  // 6. Third assistant turn — final text response, NEW message.id
114	  {
115	    message: {
116	      content: [
117	        {
118	          text: 'I fixed the bug in `/src/app.ts`. The `add` function was subtracting instead of adding.',
119	          type: 'text',
120	        },
121	      ],
122	      id: 'msg_03',
123	      model: 'claude-sonnet-4-6',
124	      role: 'assistant',
125	      usage: { input_tokens: 1000, output_tokens: 30 },
126	    },
127	    type: 'assistant',
128	  },
129	  // 7. Final result
130	  {
131	    is_error: false,
132	    result: 'I fixed the bug in `/src/app.ts`.',
133	    type: 'result',
134	  },
135	];
136	
137	describe('ClaudeCodeAdapter E2E', () => {
138	  it('produces correct event sequence for a multi-step session', () => {
139	    const adapter = new ClaudeCodeAdapter();
140	    const allEvents = simulatedStream.flatMap((line) => adapter.adapt(line));
