2	 * Agent Adapter Registry
3	 *
4	 * Maps agent type keys to their adapter constructors and CLI presets.
5	 * New agents are added by registering here — no other code changes needed.
6	 */
7	
8	import { ClaudeCodeAdapter, claudeCodePreset } from './adapters';
