11	interface AgentRegistryEntry {
12	  createAdapter: () => AgentEventAdapter;
13	  preset: AgentCLIPreset;
14	}
15	
16	const registry: Record<string, AgentRegistryEntry> = {
17	  'claude-code': {
18	    createAdapter: () => new ClaudeCodeAdapter(),
19	    preset: claudeCodePreset,
20	  },
21	  // Future:
22	  // 'codex': { createAdapter: () => new CodexAdapter(), preset: codexPreset },
23	  // 'kimi-cli': { createAdapter: () => new KimiCLIAdapter(), preset: kimiPreset },
24	};
25	
26	/**
27	 * Create an adapter instance for the given agent type.
28	 */
29	export const createAdapter = (agentType: string): AgentEventAdapter => {
30	  const entry = registry[agentType];
31	  if (!entry) {
32	    throw new Error(
33	      `Unknown agent type: "${agentType}". Available: ${Object.keys(registry).join(', ')}`,
