1	import type { ChildProcess } from 'node:child_process';
2	import { spawn } from 'node:child_process';
3	import { randomUUID } from 'node:crypto';
4	import { mkdir, readFile, writeFile } from 'node:fs/promises';
5	import { join } from 'node:path';
6	import type { Readable, Writable } from 'node:stream';
7	
8	import { app as electronApp, BrowserWindow } from 'electron';
9	
10	import { createLogger } from '@/utils/logger';
11	
12	import { ControllerModule, IpcMethod } from './index';
13	
14	const logger = createLogger('controllers:HeterogeneousAgentCtr');
15	
16	/** Directory under appStoragePath for caching downloaded files */
17	const FILE_CACHE_DIR = 'heteroAgent/files';
18	
19	// ─── CLI presets per agent type ───
20	// Mirrors @lobechat/heterogeneous-agents/registry but runs in main process
21	// (can't import from the workspace package in Electron main directly)
22	
23	interface CLIPreset {
24	  baseArgs: string[];
25	  promptMode: 'positional' | 'stdin';
26	  resumeArgs?: (sessionId: string) => string[];
27	}
28	
29	const CLI_PRESETS: Record<string, CLIPreset> = {
30	  'claude-code': {
31	    baseArgs: [
32	      '-p',
33	      '--output-format',
34	      'stream-json',
35	      '--verbose',
36	      '--permission-mode',
37	      'bypassPermissions',
38	    ],
39	    promptMode: 'positional',
40	    resumeArgs: (sid) => ['--resume', sid],
41	  },
42	  // Future presets:
43	  // 'codex': { baseArgs: [...], promptMode: 'positional' },
44	  // 'kimi-cli': { baseArgs: [...], promptMode: 'positional' },
45	};
46	
47	// ─── IPC types ───
48	
49	interface StartSessionParams {
50	  /** Agent type key (e.g., 'claude-code'). Defaults to 'claude-code'. */
51	  agentType?: string;
52	  /** Additional CLI arguments */
53	  args?: string[];
54	  /** Command to execute */
55	  command: string;
56	  /** Working directory */
57	  cwd?: string;
58	  /** Environment variables */
59	  env?: Record<string, string>;
60	  /** Session ID to resume (for multi-turn) */
61	  resumeSessionId?: string;
62	}
63	
64	interface StartSessionResult {
65	  sessionId: string;
66	}
67	
68	interface ImageAttachment {
69	  id: string;
70	  url: string;
71	}
72	
73	interface SendPromptParams {
74	  /** Image attachments to include in the prompt (downloaded from url, cached by id) */
75	  imageList?: ImageAttachment[];
76	  prompt: string;
77	  sessionId: string;
78	}
79	
80	interface CancelSessionParams {
81	  sessionId: string;
82	}
83	
84	interface StopSessionParams {
85	  sessionId: string;
86	}
87	
88	interface GetSessionInfoParams {
89	  sessionId: string;
90	}
91	
92	interface SessionInfo {
93	  agentSessionId?: string;
94	}
95	
96	// ─── Internal session tracking ───
97	
98	interface AgentSession {
99	  agentSessionId?: string;
100	  agentType: string;
101	  args: string[];
102	  command: string;
103	  cwd?: string;
104	  env?: Record<string, string>;
105	  process?: ChildProcess;
106	  sessionId: string;
107	}
108	
109	/**
110	 * External Agent Controller — manages external agent CLI processes via Electron IPC.
111	 *
112	 * Agent-agnostic: uses CLI presets from a registry to support Claude Code,
113	 * Codex, Kimi CLI, etc. Only handles process lifecycle and raw stdout line
114	 * broadcasting. All event parsing and DB persistence happens on the Renderer side.
115	 *
116	 * Lifecycle: startSession → sendPrompt → (heteroAgentRawLine broadcasts) → stopSession
117	 */
118	export default class HeterogeneousAgentCtr extends ControllerModule {
119	  static override readonly groupName = 'heterogeneousAgent';
120	
121	  private sessions = new Map<string, AgentSession>();
122	
123	  // ─── Broadcast ───
124	
125	  private broadcast<T>(channel: string, data: T) {
126	    for (const win of BrowserWindow.getAllWindows()) {
127	      if (!win.isDestroyed()) {
128	        win.webContents.send(channel, data);
129	      }
130	    }
131	  }
132	
133	  // ─── File cache ───
134	
135	  private get fileCacheDir(): string {
136	    return join(this.app.appStoragePath, FILE_CACHE_DIR);
137	  }
138	
139	  /**
140	   * Download an image by URL, with local disk cache keyed by id.
141	   */
142	  private async resolveImage(
143	    image: ImageAttachment,
144	  ): Promise<{ buffer: Buffer; mimeType: string }> {
145	    const cacheDir = this.fileCacheDir;
146	    const metaPath = join(cacheDir, `${image.id}.meta`);
147	    const dataPath = join(cacheDir, image.id);
148	
149	    // Check cache first
150	    try {
151	      const metaRaw = await readFile(metaPath, 'utf8');
152	      const meta = JSON.parse(metaRaw);
153	      const buffer = await readFile(dataPath);
154	      logger.debug('Image cache hit:', image.id);
155	      return { buffer, mimeType: meta.mimeType || 'image/png' };
