1	/**
2	 * Tests for heterogeneousAgentExecutor DB persistence layer.
3	 *
4	 * Verifies the critical path: CC stream events → messageService DB writes.
5	 * Covers:
6	 *   - Tool 3-phase persistence (pre-register → create → backfill)
7	 *   - Tool result content updates
8	 *   - Multi-step assistant message creation with correct parentId chain
9	 *   - Content/reasoning/model/usage final writes
10	 *   - Sync snapshot + reset to prevent cross-step content contamination
11	 */
12	import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
13	
14	import { executeHeterogeneousAgent } from '../heterogeneousAgentExecutor';
15	
16	// ─── Mocks ───
17	
18	// messageService — the DB layer under test
19	const mockCreateMessage = vi.fn();
20	const mockUpdateMessage = vi.fn();
21	const mockUpdateToolMessage = vi.fn();
22	const mockGetMessages = vi.fn();
23	
24	vi.mock('@/services/message', () => ({
25	  messageService: {
26	    createMessage: (...args: any[]) => mockCreateMessage(...args),
27	    getMessages: (...args: any[]) => mockGetMessages(...args),
28	    updateMessage: (...args: any[]) => mockUpdateMessage(...args),
29	    updateToolMessage: (...args: any[]) => mockUpdateToolMessage(...args),
30	  },
31	}));
32	
33	// heterogeneousAgentService — IPC to Electron main
34	const mockStartSession = vi.fn();
35	const mockSendPrompt = vi.fn();
36	const mockStopSession = vi.fn();
37	const mockGetSessionInfo = vi.fn();
38	
39	vi.mock('@/services/electron/heterogeneousAgent', () => ({
40	  heterogeneousAgentService: {
41	    getSessionInfo: (...args: any[]) => mockGetSessionInfo(...args),
42	    sendPrompt: (...args: any[]) => mockSendPrompt(...args),
43	    startSession: (...args: any[]) => mockStartSession(...args),
44	    stopSession: (...args: any[]) => mockStopSession(...args),
45	  },
46	}));
47	
48	// Gateway event handler — we spy on it but let it run (it calls getMessages)
49	vi.mock('../gatewayEventHandler', () => ({
50	  createGatewayEventHandler: vi.fn(() => vi.fn()),
51	}));
52	
53	// ─── Helpers ───
54	
55	function setupIpcCapture() {
56	  // Mock window.electron.ipcRenderer
57	  const listeners = new Map<string, (...args: any[]) => void>();
58	  (globalThis as any).window = {
59	    electron: {
60	      ipcRenderer: {
61	        on: vi.fn((channel: string, handler: (...args: any[]) => void) => {
62	          listeners.set(channel, handler);
63	        }),
64	        removeListener: vi.fn(),
65	      },
66	    },
67	  };
68	
69	  // After subscribeBroadcasts is called, extract the callbacks
70	  // by intercepting the IPC .on() calls
71	  return {
72	    getListeners: () => listeners,
73	    /** Simulate a raw line broadcast from Electron main */
74	    emitRawLine: (sessionId: string, line: any) => {
75	      const handler = listeners.get('heteroAgentRawLine');
76	      handler?.(null, { line, sessionId });
77	    },
78	    /** Simulate session completion */
79	    emitComplete: (sessionId: string) => {
80	      const handler = listeners.get('heteroAgentSessionComplete');
81	      handler?.(null, { sessionId });
82	    },
83	    /** Simulate session error */
84	    emitError: (sessionId: string, error: string) => {
85	      const handler = listeners.get('heteroAgentSessionError');
86	      handler?.(null, { error, sessionId });
87	    },
88	  };
89	}
90	
91	function createMockStore() {
92	  return {
93	    associateMessageWithOperation: vi.fn(),
94	    completeOperation: vi.fn(),
95	    internal_dispatchMessage: vi.fn(),
96	    internal_toggleToolCallingStreaming: vi.fn(),
97	    replaceMessages: vi.fn(),
98	  } as any;
99	}
100	
101	const defaultContext = {
102	  agentId: 'agent-1',
103	  scope: 'session' as const,
104	  topicId: 'topic-1',
105	};
106	
107	const defaultParams = {
108	  assistantMessageId: 'ast-initial',
109	  context: defaultContext,
110	  heterogeneousProvider: { command: 'claude', type: 'claudecode' as const },
111	  message: 'test prompt',
112	  operationId: 'op-1',
113	};
114	
115	/** Flush async queues */
116	const flush = async () => {
117	  for (let i = 0; i < 10; i++) {
118	    await new Promise((r) => setTimeout(r, 10));
119	  }
120	};
121	
122	// ─── CC stream-json event factories ───
123	
124	const ccInit = (sessionId = 'cc-sess-1') => ({
125	  model: 'claude-sonnet-4-6',
126	  session_id: sessionId,
127	  subtype: 'init',
128	  type: 'system',
129	});
130	
131	const ccAssistant = (msgId: string, content: any[], extra?: { model?: string; usage?: any }) => ({
132	  message: {
133	    content,
134	    id: msgId,
135	    model: extra?.model || 'claude-sonnet-4-6',
136	    role: 'assistant',
137	    usage: extra?.usage,
138	  },
139	  type: 'assistant',
140	});
141	
142	const ccToolUse = (msgId: string, toolId: string, name: string, input: any = {}) =>
143	  ccAssistant(msgId, [{ id: toolId, input, name, type: 'tool_use' }]);
144	
145	const ccText = (msgId: string, text: string) => ccAssistant(msgId, [{ text, type: 'text' }]);
146	
147	const ccThinking = (msgId: string, thinking: string) =>
148	  ccAssistant(msgId, [{ thinking, type: 'thinking' }]);
149	
150	const ccToolResult = (toolUseId: string, content: string, isError = false) => ({
151	  message: {
152	    content: [{ content, is_error: isError, tool_use_id: toolUseId, type: 'tool_result' }],
153	    role: 'user',
154	  },
155	  type: 'user',
156	});
157	
158	const ccResult = (isError = false, result = 'done') => ({
159	  is_error: isError,
160	  result,
161	  type: 'result',
162	});
163	
164	// ─── Tests ───
165	
166	describe('heterogeneousAgentExecutor DB persistence', () => {
167	  let ipc: ReturnType<typeof setupIpcCapture>;
168	
169	  beforeEach(() => {
170	    vi.clearAllMocks();
171	    ipc = setupIpcCapture();
172	    mockStartSession.mockResolvedValue({ sessionId: 'ipc-sess-1' });
173	    mockSendPrompt.mockResolvedValue(undefined);
174	    mockStopSession.mockResolvedValue(undefined);
175	    mockGetSessionInfo.mockResolvedValue({ agentSessionId: 'cc-sess-1' });
176	    mockGetMessages.mockResolvedValue([]);
177	    mockCreateMessage.mockImplementation(async (params: any) => ({
178	      id: `created-${params.role}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
179	    }));
180	    mockUpdateMessage.mockResolvedValue(undefined);
181	    mockUpdateToolMessage.mockResolvedValue(undefined);
182	  });
183	
184	  afterEach(() => {
185	    delete (globalThis as any).window;
186	  });
187	
188	  /**
189	   * Runs the executor in background, then feeds CC events and completes.
190	   * Returns a promise that resolves when the executor finishes.
191	   */
192	  async function runWithEvents(ccEvents: any[], opts?: { params?: Partial<typeof defaultParams> }) {
193	    const store = createMockStore();
194	    const get = vi.fn(() => store);
195	
196	    // sendPrompt will resolve after we emit all events
197	    let resolveSendPrompt: () => void;
198	    mockSendPrompt.mockReturnValue(
199	      new Promise<void>((r) => {
200	        resolveSendPrompt = r;
201	      }),
202	    );
203	
204	    const executorPromise = executeHeterogeneousAgent(get, {
205	      ...defaultParams,
206	      ...opts?.params,
207	    });
208	
209	    // Wait for startSession + subscribeBroadcasts to complete
210	    await flush();
211	
212	    // Feed CC events
213	    for (const event of ccEvents) {
214	      ipc.emitRawLine('ipc-sess-1', event);
215	    }
216	
217	    // Signal completion
218	    ipc.emitComplete('ipc-sess-1');
219	    await flush();
220	
221	    // Resolve sendPrompt to let executor continue
222	    resolveSendPrompt!();
223	    await flush();
224	
225	    // Wait for executor to finish
226	    await executorPromise;
227	    await flush();
228	
229	    return { get, store };
230	  }
231	
232	  // ────────────────────────────────────────────────────
233	  // Tool 3-phase persistence
234	  // ────────────────────────────────────────────────────
235	
236	  describe('tool 3-phase persistence', () => {
237	    it('should pre-register tools, create tool messages, then backfill result_msg_id', async () => {
238	      // Track createMessage call order and IDs
239	      let toolMsgCounter = 0;
240	      mockCreateMessage.mockImplementation(async (params: any) => {
241	        if (params.role === 'tool') {
242	          toolMsgCounter++;
243	          return { id: `tool-msg-${toolMsgCounter}` };
244	        }
245	        return { id: `msg-${params.role}-${Date.now()}` };
246	      });
247	
248	      await runWithEvents([
249	        ccInit(),
250	        ccToolUse('msg_01', 'toolu_1', 'Read', { file_path: '/a.ts' }),
251	        ccToolResult('toolu_1', 'file content'),
252	        ccText('msg_02', 'Done'),
253	        ccResult(),
254	      ]);
255	
256	      // Phase 1 + Phase 3: updateMessage called with tools[] on the assistant
257	      // Phase 1 has tools without result_msg_id, Phase 3 has tools with result_msg_id
258	      const toolUpdateCalls = mockUpdateMessage.mock.calls.filter(
259	        ([id, val]: any) => id === 'ast-initial' && val.tools?.length > 0,
260	      );
261	      // At least 2 calls: phase 1 (pre-register) + phase 3 (backfill)
262	      expect(toolUpdateCalls.length).toBeGreaterThanOrEqual(2);
263	
264	      // Phase 2: createMessage called with role='tool'
265	      const toolCreateCalls = mockCreateMessage.mock.calls.filter(
266	        ([params]: any) => params.role === 'tool',
267	      );
268	      expect(toolCreateCalls.length).toBe(1);
269	      expect(toolCreateCalls[0][0]).toMatchObject({
270	        parentId: 'ast-initial',
271	        role: 'tool',
272	        tool_call_id: 'toolu_1',
273	        plugin: expect.objectContaining({ apiName: 'Read' }),
274	      });
275	
276	      // Phase 3: the last tools[] write should have result_msg_id backfilled
277	      const lastToolUpdate = toolUpdateCalls.at(-1);
278	      expect(lastToolUpdate[1].tools[0].result_msg_id).toBe('tool-msg-1');
279	    });
280	
281	    it('should deduplicate tool calls (idempotent)', async () => {
282	      await runWithEvents([
283	        ccInit(),
284	        // Same tool_use id sent twice (CC can echo tool blocks)
285	        ccToolUse('msg_01', 'toolu_1', 'Bash', { command: 'ls' }),
286	        ccAssistant('msg_01', [
287	          { id: 'toolu_1', input: { command: 'ls' }, name: 'Bash', type: 'tool_use' },
288	        ]),
289	        ccToolResult('toolu_1', 'output'),
290	        ccResult(),
291	      ]);
292	
293	      // Should only create ONE tool message despite two tool_use events with same id
294	      const toolCreates = mockCreateMessage.mock.calls.filter(([p]: any) => p.role === 'tool');
295	      expect(toolCreates.length).toBe(1);
296	    });
297	  });
298	
299	  // ────────────────────────────────────────────────────
300	  // Tool result content persistence
301	  // ────────────────────────────────────────────────────
302	
303	  describe('tool result persistence', () => {
304	    it('should update tool message content on tool_result', async () => {
305	      mockCreateMessage.mockImplementation(async (params: any) => {
306	        if (params.role === 'tool') return { id: 'tool-msg-read' };
307	        return { id: `msg-${Date.now()}` };
308	      });
309	
310	      await runWithEvents([
311	        ccInit(),
312	        ccToolUse('msg_01', 'toolu_read', 'Read', { file_path: '/x.ts' }),
313	        ccToolResult('toolu_read', 'the file content here'),
314	        ccResult(),
315	      ]);
316	
317	      expect(mockUpdateToolMessage).toHaveBeenCalledWith(
318	        'tool-msg-read',
319	        { content: 'the file content here', pluginError: undefined },
320	        { agentId: 'agent-1', topicId: 'topic-1' },
321	      );
322	    });
323	
324	    it('should mark error tool results with pluginError', async () => {
325	      mockCreateMessage.mockImplementation(async (params: any) => {
326	        if (params.role === 'tool') return { id: 'tool-msg-err' };
327	        return { id: `msg-${Date.now()}` };
328	      });
329	
330	      await runWithEvents([
331	        ccInit(),
332	        ccToolUse('msg_01', 'toolu_fail', 'Read', { file_path: '/nope' }),
333	        ccToolResult('toolu_fail', 'ENOENT: no such file', true),
334	        ccResult(),
335	      ]);
336	
337	      expect(mockUpdateToolMessage).toHaveBeenCalledWith(
338	        'tool-msg-err',
339	        { content: 'ENOENT: no such file', pluginError: { message: 'ENOENT: no such file' } },
340	        { agentId: 'agent-1', topicId: 'topic-1' },
341	      );
342	    });
343	  });
344	
345	  // ────────────────────────────────────────────────────
346	  // Multi-step parentId chain
347	  // ────────────────────────────────────────────────────
348	
349	  describe('multi-step parentId chain', () => {
350	    it('should create assistant messages chained: assistant → tool → assistant', async () => {
351	      const createdIds: string[] = [];
352	      mockCreateMessage.mockImplementation(async (params: any) => {
353	        const id =
354	          params.role === 'tool' ? `tool-${createdIds.length}` : `ast-step-${createdIds.length}`;
355	        createdIds.push(id);
356	        return { id };
357	      });
358	
359	      await runWithEvents([
360	        ccInit(),
361	        // Step 1: tool_use Read
362	        ccToolUse('msg_01', 'toolu_1', 'Read', { file_path: '/a.ts' }),
363	        ccToolResult('toolu_1', 'content of a.ts'),
364	        // Step 2 (new message.id): tool_use Write
365	        ccToolUse('msg_02', 'toolu_2', 'Write', { file_path: '/b.ts', content: 'new' }),
366	        ccToolResult('toolu_2', 'file written'),
367	        // Step 3 (new message.id): final text
368	        ccText('msg_03', 'All done!'),
369	        ccResult(),
370	      ]);
371	
372	      // Collect all createMessage calls with their parentId
373	      // Tool message for step 1 — parentId should be the initial assistant
374	      const tool1Create = mockCreateMessage.mock.calls.find(
375	        ([p]: any) => p.role === 'tool' && p.tool_call_id === 'toolu_1',
376	      );
377	      expect(tool1Create?.[0].parentId).toBe('ast-initial');
378	
379	      // Assistant for step 2 — parentId should be step 1's TOOL message (not assistant)
380	      const step2Assistant = mockCreateMessage.mock.calls.find(
381	        ([p]: any) => p.role === 'assistant' && p.parentId !== undefined,
382	      );
383	      expect(step2Assistant).toBeDefined();
384	      // The parentId should be the tool message ID from step 1
385	      const tool1Id = createdIds.find((id) => id.startsWith('tool-'));
386	      expect(step2Assistant![0].parentId).toBe(tool1Id);
387	    });
388	
389	    it('should fall back to assistant parentId when step has no tools', async () => {
390	      const ids: string[] = [];
391	      mockCreateMessage.mockImplementation(async (params: any) => {
392	        const id = `${params.role}-${ids.length}`;
393	        ids.push(id);
394	        return { id };
395	      });
